/* DAWAH X — ahmad, অধ্যায় 80 · খণ্ড 80 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][80]=[[15801,15801,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏أَنَّهُ ‏ ‏صَلَّى خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَهُ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْفَجْرِ ‏ ‏ق وَالْقُرْآنِ الْمَجِيدِ ‏ ‏وَيس وَالْقُرْآنِ الْحَكِيمِ ‏","","",""],[15802,15802,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ثَلَاثٌ حَقٌّ عَلَى كُلِّ مُسْلِمٍ الْغُسْلُ يَوْمَ الْجُمُعَةِ وَالسِّوَاكُ وَيَمَسُّ مِنْ طِيبٍ إِنْ وَجَدَ ‏","","",""],[15803,15803,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَقٌّ عَلَى كُلِّ مُسْلِمٍ يَغْتَسِلُ يَوْمَ الْجُمُعَةِ يَتَسَوَّكُ وَيَمَسُّ مِنْ طِيبٍ إِنْ كَانَ لِأَهْلِهِ ‏","","",""],[15804,15804,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمُّ كُلْثُومٍ ابْنَةُ عَلِيٍّ ‏ ‏قَالَ أَتَيْتُهَا ‏ ‏بِصَدَقَةٍ ‏ ‏كَانَ أُمِرَ بِهَا قَالَتْ أَحَدُ رَبَائِبِنَا فَإِنَّ ‏ ‏مَيْمُونَ ‏ ‏أَوْ ‏ ‏مِهْرَانَ ‏ ‏مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَنِي أَنَّهُ ‏ ‏مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ يَا ‏ ‏مَيْمُونُ ‏ ‏أَوْ يَا ‏ ‏مِهْرَانُ ‏ ‏إِنَّا أَهْلُ بَيْتٍ نُهِينَا عَنْ ‏ ‏الصَّدَقَةِ ‏ ‏وَإِنَّ ‏ ‏مَوَالِيَنَا ‏ ‏مِنْ أَنْفُسِنَا وَلَا نَأْكُلُ ‏ ‏الصَّدَقَةَ ‏","","",""],[15805,15805,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَرْقَمَ ‏ ‏أَنَّهُ ‏ ‏خَرَجَ مِنْ ‏ ‏مَكَّةَ ‏ ‏وَكَانَ يَؤُمُّهُمْ وَيُؤَذِّنُ وَيُقِيمُ فَأَقَامَ يَوْمًا الصَّلَاةَ فَقَالَ لِيُصَلِّ بِكُمْ رَجُلٌ مِنْكُمْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ أَنْ يَذْهَبَ إِلَى الْخَلَاءِ وَأُقِيمَتْ الصَّلَاةُ فَلْيَذْهَبْ إِلَى الْخَلَاءِ ‏","","",""],[15806,15806,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَقْرَمَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ أَبِيهِ ‏ ‏بِالْقَاعِ ‏ ‏مِنْ ‏ ‏نَمِرَةَ ‏ ‏فَمَرَّ بِنَا ‏ ‏رَكْبٌ ‏ ‏فَقَالَ أَبِي يَا بُنَيَّ كُنْ فِي ‏ ‏بَهْمِكَ ‏ ‏حَتَّى آتِيَ هَؤُلَاءِ الْقَوْمَ فَأُسَائِلَهُمْ ‏ ‏فَدَنَا ‏ ‏وَدَنَوْتُ ‏ ‏فَكُنْتُ أَنْظُرُ إِلَى ‏ ‏عُفْرَتَيْ ‏ ‏إِبْطَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ سَاجِدٌ ‏","","",""],[15807,15807,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَقْرَمَ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ أَبِي ‏ ‏أَقْرَمَ ‏ ‏بِالْقَاعِ ‏ ‏قَالَ فَمَرَّ بِنَا ‏ ‏رَكْبٌ ‏ ‏فَأَنَاخُوا ‏ ‏بِنَاحِيَةِ الطَّرِيقِ فَقَالَ لِي أَبِي أَيْ بُنَيَّ كُنْ فِي ‏ ‏بَهْمِكَ ‏ ‏حَتَّى آتِيَ هَؤُلَاءِ الْقَوْمَ وَأُسَائِلَهُمْ قَالَ فَخَرَجَ وَخَرَجْتُ فِي ‏ ‏أَثَرِهِ ‏ ‏فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَحَضَرَتْ الصَّلَاةُ ‏ ‏فَصَلَّيْتُ مَعَهُ فَكُنْتُ أَنْظُرُ إِلَى ‏ ‏عُفْرَتَيْ ‏ ‏إِبْطَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّمَا سَجَدَ ‏","","",""],[15808,15808,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ قَيْسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ أَقْرَمَ الْخُزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ كَانَ مَعَ أَبِيهِ ‏ ‏بِالْقَاعِ ‏ ‏مِنْ ‏ ‏نَمِرَةَ ‏ ‏قَالَ فَمَرَّ بِنَا ‏ ‏رَكْبٌ ‏ ‏فَأَنَاخُوا ‏ ‏بِنَاحِيَةِ الطَّرِيقِ فَقَالَ أَبِي أَيْ بُنَيَّ كُنْ فِي ‏ ‏بَهْمِكَ ‏ ‏حَتَّى آتِيَ هَؤُلَاءِ ‏ ‏الرَّكْبَ ‏ ‏فَأُسَائِلَهُمْ قَالَ ‏ ‏دَنَا ‏ ‏مِنْهُمْ ‏ ‏وَدَنَوْتُ ‏ ‏مِنْهُ وَأُقِيمَتْ الصَّلَاةُ فَإِذَا فِيهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّيْتُ مَعَهُمْ وَكَأَنِّي أَنْظُرُ إِلَى ‏ ‏عُفْرَتَيْ ‏ ‏إِبْطَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَجَدَ ‏","","",""],[15809,15809,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي الْهَيْثَمِ الْعَطَّارُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏سَمِعَهُ مِنْ ‏ ‏يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏قَالَ ‏ ‏سَمَّانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوسُفَ ‏ ‏وَمَسَحَ عَلَى رَأْسِي ‏","","",""],[15810,15810,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏نَضْرِ بْنِ قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏يَقُولُ ‏ ‏سَمَّانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوسُفَ ‏","","",""],[15811,15811,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِرَجُلٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَامْرَأَتِهِ اعْتَمِرَا فِي رَمَضَانَ فَإِنَّ ‏ ‏عُمْرَةً فِي رَمَضَانَ لَكُمَا كَحَجَّةٍ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً وَلَمْ يَقُلْ حَدَّثَنِي ‏ ‏يَعْنِي ‏ ‏ابْنَ الْمُنْكَدِرِ ‏ ‏فَإِنَّ عُمْرَةً فِيهِ كَحَجَّةٍ ‏","","",""],[15812,15812,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي الْهَيْثَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُوسُفَ بْنَ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏يَقُولُ ‏ ‏أَجْلَسَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجْرِهِ وَمَسَحَ عَلَى رَأْسِي وَسَمَّانِي ‏ ‏يُوسُفَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَلَّامُ بْنُ عَبْدِ اللَّهِ بْنِ مِسْكِينٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ بْنِ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏وَذَكَرَ الْحَدِيثَ الْمَارَّ ‏","","",""],[15813,15813,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ يَعْنِي ابْنَ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَرِقَّاءَكُمْ ‏ ‏أَرِقَّاءَكُمْ ‏ ‏أَرِقَّاءَكُمْ ‏ ‏أَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ وَاكْسُوهُمْ مِمَّا تَلْبَسُونَ فَإِنْ جَاءُوا بِذَنْبٍ لَا تُرِيدُونَ أَنْ تَغْفِرُوهُ فَبِيعُوا عِبَادَ اللَّهِ وَلَا تُعَذِّبُوهُمْ ‏","","",""],[15814,15814,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي رَبِيعَةَ الْمَخْزُومِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَسْلَفَ ‏ ‏مِنْهُ حِينَ غَزَا ‏ ‏حُنَيْنًا ‏ ‏ثَلَاثِينَ ‏ ‏أَوْ أَرْبَعِينَ ‏ ‏أَلْفًا فَلَمَّا انْصَرَفَ ‏ ‏قَضَاهَا ‏ ‏إِيَّاهُ ثُمَّ قَالَ ‏ ‏بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ إِنَّمَا جَزَاءُ ‏ ‏السَّلَفِ ‏ ‏الْوَفَاءُ وَالْحَمْدُ ‏","","",""],[15815,15815,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي أَسَدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ وَلَهُ ‏ ‏أُوقِيَّةٌ ‏ ‏أَوْ ‏ ‏عَدْلُهَا ‏ ‏فَقَدْ سَأَلَ ‏ ‏إِلْحَافًا ‏","","",""],[15816,15816,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْضَلُ الْكَلَامِ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ ‏","","",""],[15817,15817,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏وَقَالَ ‏ ‏غُنْدَرٌ ‏ ‏عَبْدُ رَبِّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏أَحْجَارِ الزَّيْتِ ‏ ‏يَدْعُو بِكَفَّيْهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَرَفَعَ ‏ ‏شُعْبَةُ ‏ ‏كَفَّيْهِ وَبَسَطَهُمَا ‏","","",""],[15818,15818,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَتِيكٍ ‏ ‏أَحَدِ ‏ ‏بَنِي سَلِمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَتِيكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ خَرَجَ مِنْ بَيْتِهِ مُجَاهِدًا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ثُمَّ قَالَ بِأَصَابِعِهِ هَؤُلَاءِ الثَّلَاثِ الْوُسْطَى وَالسَّبَّابَةِ وَالْإِبْهَامِ فَجَمَعَهُنَّ وَقَالَ وَأَيْنَ الْمُجَاهِدُونَ ‏ ‏فَخَرَّ ‏ ‏عَنْ دَابَّتِهِ ‏ ‏فَمَاتَ ‏ ‏فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ تَعَالَى أَوْ ‏ ‏لَدَغَتْهُ ‏ ‏دَابَّةٌ فَمَاتَ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ أَوْ مَاتَ ‏ ‏حَتْفَ ‏ ‏أَنْفِهِ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ عَزَّ وَجَلَّ وَاللَّهِ إِنَّهَا لَكَلِمَةٌ مَا سَمِعْتُهَا مِنْ أَحَدٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏قَبْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَاتَ فَقَدْ وَقَعَ أَجْرُهُ عَلَى اللَّهِ تَعَالَى وَمَنْ مَاتَ ‏ ‏قَعْصًا ‏ ‏فَقَدْ اسْتَوْجَبَ ‏ ‏الْمَآبَ ‏","","",""],[15819,15819,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ بِلَالٍ ‏ ‏عَنْ ‏ ‏نَاسٍ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَغْرِبَ ثُمَّ نَنْصَرِفُ ‏ ‏فَنَتَرَامَى حَتَّى نَأْتِيَ دِيَارَنَا فَمَا ‏ ‏يَخْفَى عَلَيْنَا مَوَاقِعُ سِهَامِنَا ‏","","",""],[15820,15820,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ بِلَالٍ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ ‏ ‏نَفَرٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثُونِي أَنَّهُمْ كَانُوا ‏ ‏يُصَلُّونَ الْمَغْرِبَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَنْطَلِقُونَ يَتَرَامَوْنَ لَا ‏ ‏يَخْفَى عَلَيْهِمْ مَوَاقِعُ سِهَامِهِمْ حَتَّى يَأْتُونَ دِيَارَهُمْ فِي أَقْصَى ‏ ‏الْمَدِينَةِ ‏","","",""],[15821,15821,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيْدٍ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رِجَالٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْرَكَهُمْ ‏ ‏يَذْكُرُونَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏ظَهَرَ ‏ ‏عَلَى ‏ ‏خَيْبَرَ ‏ ‏وَصَارَتْ ‏ ‏خَيْبَرُ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمُسْلِمِينَ ‏ ‏ضَعُفُوا ‏ ‏عَنْ عَمَلِهَا فَدَفَعُوهَا إِلَى ‏ ‏الْيَهُودِ ‏ ‏يَقُومُونَ عَلَيْهَا وَيُنْفِقُونَ عَلَيْهَا عَلَى أَنَّ لَهُمْ نِصْفَ مَا ‏ ‏يَخْرُجُ ‏ ‏مِنْهَا فَقَسَمَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى سِتَّةٍ وَثَلَاثِينَ سَهْمًا جَمَعَ كُلُّ سَهْمٍ مِائَةَ سَهْمٍ فَجَعَلَ نِصْفَ ذَلِكَ كُلِّهِ لِلْمُسْلِمِينَ وَكَانَ فِي ذَلِكَ النِّصْفِ سِهَامُ الْمُسْلِمِينَ وَسَهْمُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهَا وَجَعَلَ النِّصْفَ الْآخَرَ لِمَنْ يَنْزِلُ بِهِ مِنْ الْوُفُودِ وَالْأُمُورِ ‏ ‏وَنَوَائِبِ ‏ ‏النَّاسِ ‏","","",""],[15822,15822,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ حَفِظْنَا عَنْ ‏ ‏ثَلَاثِينَ مِنْ أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِقْصًا ‏ ‏لَهُ فِي مَمْلُوكٍ ضَمِنَ بَقِيَّتَهُ ‏","","",""],[15823,15823,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ الْمُلَائِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي فَرْوَةَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ صَخْرٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏تَظَاهَرْتُ ‏ ‏مِنْ امْرَأَتِي ثُمَّ ‏ ‏وَقَعْتُ ‏ ‏بِهَا قَبْلَ أَنْ أُكَفِّرَ فَسَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَفْتَانِي بِالْكَفَّارَةِ ‏","","",""],[15824,15824,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ صَخْرٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏تَظَاهَرْتُ ‏ ‏مِنْ امْرَأَتِي ثُمَّ ‏ ‏وَقَعْتُ ‏ ‏بِهَا قَبْلَ أَنْ أُكَفِّرَ فَسَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَفْتَانِي بِالْكَفَّارَةِ ‏","","",""],[15825,15825,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ صَخْرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ امْرَأً قَدْ أُوتِيتُ مِنْ جِمَاعِ النِّسَاءِ مَا لَمْ يُؤْتَ غَيْرِي فَلَمَّا دَخَلَ رَمَضَانُ ‏ ‏تَظَاهَرْتُ ‏ ‏مِنْ امْرَأَتِي حَتَّى ‏ ‏يَنْسَلِخَ ‏ ‏رَمَضَانُ ‏ ‏فَرَقًا ‏ ‏مِنْ أَنْ أُصِيبَ فِي لَيْلَتِي شَيْئًا فَأَتَتَابَعُ فِي ذَلِكَ إِلَى أَنْ يُدْرِكَنِي النَّهَارُ وَأَنَا لَا أَقْدِرُ عَلَى أَنْ ‏ ‏أَنْزِعَ ‏ ‏فَبَيْنَا هِيَ تَخْدُمُنِي إِذْ تَكَشَّفَ لِي مِنْهَا شَيْءٌ ‏ ‏فَوَثَبْتُ ‏ ‏عَلَيْهَا فَلَمَّا أَصْبَحْتُ ‏ ‏غَدَوْتُ ‏ ‏عَلَى قَوْمِي فَأَخْبَرْتُهُمْ خَبَرِي وَقُلْتُ لَهُمْ انْطَلِقُوا مَعِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُخْبِرُهُ بِأَمْرِي فَقَالُوا لَا وَاللَّهِ لَا نَفْعَلُ نَتَخَوَّفُ أَنْ يَنْزِلَ فِينَا قُرْآنٌ أَوْ يَقُولَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقَالَةً يَبْقَى عَلَيْنَا عَارُهَا وَلَكِنْ اذْهَبْ أَنْتَ فَاصْنَعْ مَا بَدَا لَكَ قَالَ فَخَرَجْتُ فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ خَبَرِي فَقَالَ لِي أَنْتَ بِذَاكَ فَقُلْتُ أَنَا بِذَاكَ فَقَالَ أَنْتَ بِذَاكَ فَقُلْتُ أَنَا بِذَاكَ قَالَ أَنْتَ بِذَاكَ قُلْتُ نَعَمْ هَا أَنَا ذَا فَأَمْضِ فِيَّ حُكْمَ اللَّهِ عَزَّ وَجَلَّ فَإِنِّي صَابِرٌ لَهُ قَالَ ‏ ‏أَعْتِقْ رَقَبَةً قَالَ فَضَرَبْتُ ‏ ‏صَفْحَةَ ‏ ‏رَقَبَتِي بِيَدِي وَقُلْتُ لَا وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَصْبَحْتُ أَمْلِكُ غَيْرَهَا قَالَ فَصُمْ شَهْرَيْنِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ وَهَلْ أَصَابَنِي مَا أَصَابَنِي إِلَّا فِي الصِّيَامِ قَالَ فَتَصَدَّقْ قَالَ فَقُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ بِتْنَا لَيْلَتَنَا هَذِهِ ‏ ‏وَحْشَاءَ ‏ ‏مَا لَنَا عَشَاءٌ قَالَ اذْهَبْ إِلَى صَاحِبِ صَدَقَةِ ‏ ‏بَنِي زُرَيْقٍ ‏ ‏فَقُلْ لَهُ فَلْيَدْفَعْهَا إِلَيْكَ فَأَطْعِمْ عَنْكَ مِنْهَا ‏ ‏وَسْقًا ‏ ‏مِنْ تَمْرٍ سِتِّينَ مِسْكِينًا ثُمَّ اسْتَعِنْ بِسَائِرِهِ عَلَيْكِ وَعَلَى عِيَالِكَ قَالَ فَرَجَعْتُ إِلَى قَوْمِي فَقُلْتُ وَجَدْتُ عِنْدَكُمْ الضِّيقَ وَسُوءَ الرَّأْيِ وَوَجَدْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّعَةَ وَالْبَرَكَةَ قَدْ أَمَرَ لِي بِصَدَقَتِكُمْ فَادْفَعُوهَا لِي قَالَ فَدَفَعُوهَا إِلَيَّ ‏","","",""],[15826,15826,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَأَهْدَيْتُ لَهُ مِنْ لَحْمِ حِمَارِ وَحْشٍ وَهُوَ مُحْرِمٌ ‏ ‏فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى فِي وَجْهِي الْكَرَاهَةَ قَالَ إِنَّهُ لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏","","",""],[15827,15827,"","","‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[15828,15828,"","","‏ ‏وَسُئِلَ عَنْ أَهْلِ الدَّارِ مِنْ الْمُشْرِكِينَ ‏ ‏يُبَيَّتُونَ ‏ ‏فَيُصَابُ مِنْ نِسَائِهِمْ ‏ ‏وَذَرَارِيِّهِمْ ‏ ‏فَقَالَ ‏ ‏هُمْ مِنْهُمْ ثُمَّ يَقُولُ ‏ ‏الزُّهْرِيُّ ‏ ‏ثُمَّ نَهَى عَنْ ذَلِكَ بَعْدُ ‏","","",""],[15829,15829,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ اللَّيْثِيِّ ‏ ‏أَنَّهُ أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏حِمَارًا وَحْشِيًّا فَرَدَّهُ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا رَأَى مَا فِي وَجْهِي قَالَ إِنَّا ‏ ‏لَمْ نَرُدَّ عَلَيْكَ إِلَّا أَنَّا حُرُمٌ ‏","","",""],[15830,15830,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ لَهُ ‏ ‏لَوْ أَنَّ خَيْلًا ‏ ‏أَغَارَتْ ‏ ‏مِنْ اللَّيْلِ فَأَصَابَتْ مِنْ أَبْنَاءِ الْمُشْرِكِينَ قَالَ هُمْ مِنْ آبَائِهِمْ ‏","","",""],[15831,15831,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏حِمَى ‏ ‏إِلَّا لِلَّهِ وَلِرَسُولِهِ ‏","","",""],[15832,15832,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا نُصِيبُ فِي ‏ ‏الْبَيَاتِ ‏ ‏مِنْ ‏ ‏ذَرَارِيِّ ‏ ‏الْمُشْرِكِينَ قَالَ هُمْ مِنْهُمْ ‏","","",""],[15833,15833,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِالْأَبْوَاءِ ‏ ‏فَأَهْدَيْتُ لَهُ حِمَارَ وَحْشٍ فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى الْكَرَاهِيَةَ فِي وَجْهِي قَالَ إِنَّهُ ‏ ‏لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏","","",""],[15834,15834,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏صَعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَرَّ بِي وَأَنَا ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَأَهْدَيْتُ لَهُ حِمَارَ وَحْشٍ فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَرَاهِيَةَ فِي وَجْهِي قَالَ ‏ ‏إِنَّهُ لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏ ‏قُلْتُ ‏ ‏لِابْنِ شِهَابٍ ‏ ‏الْحِمَارُ ‏ ‏عَقِيرٌ ‏ ‏قَالَ ‏ ‏لَا أَدْرِي ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنِ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّهُ أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارَ وَحْشٍ وَهُوَ مُحْرِمٌ ‏ ‏فَذَكَرَهُ ‏","","",""],[15835,15835,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ فِي الْمَسْجِدِ ‏ ‏وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏","","",""],[15836,15836,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ جَدَّهُ قَالَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَسْتَطِيعُ أَنْ تُرِيَنِي كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏نَعَمْ ‏ ‏فَدَعَا بِوَضُوءٍ فَأَفْرَغَ عَلَى يَدَيْهِ فَغَسَلَ يَدَهُ مَرَّتَيْنِ ثُمَّ تَمَضْمَضَ ‏ ‏وَاسْتَنْثَرَ ‏ ‏ثَلَاثًا ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا ثُمَّ غَسَلَ يَدَيْهِ مَرَّتَيْنِ إِلَى الْمِرْفَقَيْنِ ثُمَّ مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا ‏ ‏وَأَدْبَرَ ‏ ‏بَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ثُمَّ غَسَلَ رِجْلَيْهِ ‏","","",""],[15837,15837,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَسْقَى ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ ‏","","",""],[15838,15838,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏","","",""],[15839,15839,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَسْقَى ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ ‏","","",""],[15840,15840,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ الْمَازِنِيَّ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمُصَلَّى ‏ ‏فَاسْتَسْقَى ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ حِينَ اسْتَقْبَلَ الْقِبْلَةَ ‏","","",""],[15841,15841,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَسْقِي فَاسْتَقْبَلَ الْقِبْلَةَ ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ وَجَهَرَ بِالْقِرَاءَةِ وَصَلَّى رَكْعَتَيْنِ ‏","","",""],[15842,15842,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاسِ ‏ ‏يَسْتَسْقِي فَصَلَّى بِهِمْ رَكْعَتَيْنِ وَجَهَرَ بِالْقِرَاءَةِ فِيهَا ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ وَدَعَا وَاسْتَقْبَلَ الْقِبْلَةَ ‏","","",""],[15843,15843,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسَحَ رَأْسَهُ بِيَدَيْهِ فَأَقْبَلَ بِهِمَا ‏ ‏وَأَدْبَرَ ‏ ‏وَبَدَأَ بِمُقَدَّمِ رَأْسِهِ ثُمَّ ذَهَبَ بِهِمَا إِلَى قَفَاهُ ثُمَّ رَدَّهُمَا حَتَّى رَجَعَ إِلَى الْمَكَانِ الَّذِي بَدَأَ مِنْهُ ‏","","",""],[15844,15844,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَسْتَسْقِي فَوَلَّى ظَهْرَهُ النَّاسَ وَاسْتَقْبَلَ الْقِبْلَةَ ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ وَجَعَلَ يَدْعُو وَصَلَّى رَكْعَتَيْنِ وَجَهَرَ بِالْقِرَاءَةِ ‏","","",""],[15845,15845,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ يَوْمًا فَمَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ فَضْلِ يَدَيْهِ ‏","","",""],[15846,15846,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ زَيْدٍ ‏ ‏سَمِعَ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَجَعَلَ يَقُولُ هَكَذَا يَدْلُكُ ‏","","",""],[15847,15847,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيِّبِ ‏ ‏وَعَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا وُضُوءَ إِلَّا فِيمَا وَجَدْتَ الرِّيحَ أَوْ سَمِعْتَ الصَّوْتَ ‏","","",""],[15848,15848,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏سُئِلَ عَنْ وُضُوءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا بِمَاءٍ فَغَسَلَ يَدَيْهِ وَمَضْمَضَ ‏ ‏وَاسْتَنْشَقَ ‏ ‏ثَلَاثًا وَغَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ وَمَسَحَ رَأْسَهُ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏مَسَحَ ‏ ‏مَالِكٌ ‏ ‏رَأْسَهُ ‏ ‏فَأَقْبَلَ بِيَدَيْهِ ‏ ‏وَأَدْبَرَ ‏ ‏بِهِمَا وَغَسَلَ رِجْلَيْهِ وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏","","",""],[15849,15849,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ جُرْجَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ أَبْصَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْتَلْقِيًا فِي الْمَسْجِدِ عَلَى ظَهْرِهِ وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏","","",""],[15850,15850,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى بْنِ عُمَارَةَ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَخَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏فَقِيلَ لَهُ تَوَضَّأْ لَنَا وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَدَعَا بِإِنَاءٍ ‏ ‏فَأَكْفَأَ مِنْهُ عَلَى يَدَيْهِ ثَلَاثًا فَغَسَلَهُمَا ثُمَّ أَدْخَلَ يَدَهُ وَاسْتَخْرَجَهَا فَمَضْمَضَ ‏ ‏وَاسْتَنْشَقَ ‏ ‏مِنْ كَفٍّ وَاحِدَةٍ فَفَعَلَ ذَلِكَ ثَلَاثًا وَاسْتَخْرَجَهَا ثُمَّ غَسَلَ وَجْهَهُ ثُمَّ أَدْخَلَ يَدَهُ وَاسْتَخْرَجَهَا فَغَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ مَرَّتَيْنِ مَرَّتَيْنِ ثُمَّ أَدْخَلَ يَدَهُ فَاسْتَخْرَجَهَا فَمَسَحَ ‏ ‏بِرَأْسِهِ فَأَقْبَلَ بِيَدِهِ ‏ ‏وَأَدْبَرَ ‏ ‏ثُمَّ غَسَلَ رِجْلَيْهِ إِلَى الْكَعْبَيْنِ ثُمَّ قَالَ هَكَذَا كَانَ وُضُوءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15851,15851,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ ‏ ‏إِبْرَاهِيمَ ‏ ‏حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏وَدَعَا لَهَا وَحَرَّمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏كَمَا حَرَّمَ ‏ ‏إِبْرَاهِيمُ ‏ ‏مَكَّةَ ‏ ‏وَدَعَوْتُ لَهُمْ فِي ‏ ‏مُدِّهَا ‏ ‏وَصَاعِهَا ‏ ‏مِثْلَ مَا دَعَا بِهِ ‏ ‏إِبْرَاهِيمُ ‏ ‏لِمَكَّةَ ‏","","",""],[15852,15852,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏","","",""],[15853,15853,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَسْقَى فَاسْتَقْبَلَ الْقِبْلَةَ ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ ‏","","",""],[15854,15854,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏مُسْتَلْقِيًا وَاضِعًا إِحْدَى رِجْلَيْهِ عَلَى الْأُخْرَى ‏","","",""],[15855,15855,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ شَكَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ يَجِدُ الشَّيْءَ فِي الصَّلَاةِ يُخَيَّلُ إِلَيْهِ أَنَّهُ قَدْ كَانَ مِنْهُ فَقَالَ ‏ ‏لَا ‏ ‏يَنْفَتِلُ ‏ ‏حَتَّى يَجِدَ رِيحًا أَوْ يَسْمَعَ صَوْتًا ‏","","",""],[15856,15856,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏سَمِعَ ‏ ‏عَبَّادَ بْنَ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمُصَلَّى ‏ ‏وَاسْتَسْقَى فَاسْتَقْبَلَ الْقِبْلَةَ وَقَلَبَ رِدَاءَهُ وَصَلَّى رَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَلْبُ الرِّدَاءِ جَعْلُ الْيَمِينِ الشِّمَالَ وَالشِّمَالِ الْيَمِينَ ‏","","",""],[15857,15857,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى بْنِ عُمَارَةَ بْنِ أَبِي حَسَنٍ الْمَازِنِيُّ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏مُنْذُ أَرْبَعٍ وَسَبْعِينَ سَنَةً وَسَأَلْتُهُ بَعْدَ ذَلِكَ بِقَلِيلٍ وَكَانَ ‏ ‏يَحْيَى ‏ ‏أَكْبَرَ مِنْهُ قَالَ ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ مِنْهُ ثَلَاثَةَ أَحَادِيثَ ‏ ‏فَغَسَلَ يَدَيْهِ مَرَّتَيْنِ وَوَجْهَهُ ثَلَاثًا وَمَسَحَ بِرَأْسِهِ مَرَّتَيْنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏سَمِعْتُهُ مِنْ ‏ ‏سُفْيَانَ ‏ ‏ثَلَاثَ مَرَّاتٍ يَقُولُ غَسَلَ رِجْلَيْهِ مَرَّتَيْنِ ‏ ‏وَقَالَ مَرَّةً مَسَحَ بِرَأْسِهِ مَرَّةً ‏ ‏وَقَالَ مَرَّتَيْنِ مَسَحَ بِرَأْسِهِ مَرَّتَيْنِ ‏","","",""],[15858,15858,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْمَازِنِيِّ ‏ ‏قَالَ ‏","","",""],[15859,15859,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَمِّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وَيَمْسَحُ بِالْمَاءِ عَلَى رِجْلَيْهِ ‏","","",""],[15860,15860,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبَّادُ بْنُ تَمِيمٍ ‏ ‏أَنَّ ‏ ‏عَمَّهُ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ بِالنَّاسِ إِلَى الْمُصَلَّى ‏ ‏يَسْتَسْقِي لَهُمْ فَقَامَ فَدَعَا قَائِمًا ثُمَّ تَوَجَّهَ قِبَلَ الْقِبْلَةِ ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ فَأُسْقُوا ‏","","",""],[15861,15861,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْرَجْتُ إِلَيْهِ مَاءً ‏ ‏فَتَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ مَرَّتَيْنِ مَرَّتَيْنِ وَمَسَحَ بِرَأْسِهِ أَقْبَلَ بِهِ وَأَدْبَرَ وَمَسَحَ بِأُذُنَيْهِ وَغَسَلَ قَدَمَيْهِ ‏","","",""],[15862,15862,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ فَضْلِ يَدَيْهِ ‏","","",""],[15863,15863,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَيْنَ هَذِهِ الْبُيُوتِ ‏ ‏يَعْنِي بُيُوتَهُ ‏ ‏إِلَى مِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ وَالْمِنْبَرُ عَلَى تُرْعَةٍ مِنْ تُرَعِ الْجَنَّةِ ‏","","",""],[15864,15864,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَبَّانُ بْنُ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏عَمُّهُ ‏ ‏الْمَازِنِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْجُحْفَةِ ‏ ‏فَمَضْمَضَ ثُمَّ ‏ ‏اسْتَنْشَقَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَغَسَلَ يَدَهُ الْيُمْنَى ثَلَاثًا ثُمَّ مَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ ‏ ‏فَضْلِ ‏ ‏يَدَيْهِ ثُمَّ غَسَلَ رِجْلَيْهِ حَتَّى ‏ ‏أَنْقَاهُمَا ‏","","",""],[15865,15865,"","","‏ ‏حَدَّثَنَا ‏ ‏سَكَنُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمَّهُ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَسْقَى ثُمَّ تَوَجَّهَ قِبَلَ الْقِبْلَةِ وَحَوَّلَ إِلَى النَّاسِ ظَهْرَهُ يَدْعُو وَحَوَّلَ رِدَاءَهُ وَصَلَّى رَكْعَتَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَلْبُ الرِّدَاءِ حَتَّى تُحَوَّلَ السَّنَةُ يَصِيرُ الْغَلَاءُ رُخْصًا ‏","","",""],[15866,15866,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا بَيْنَ مِنْبَرِي وَبَيْنَ بَيْتِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ ‏","","",""],[15867,15867,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَسْقَى وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏لَهُ سَوْدَاءُ فَأَرَادَ أَنْ يَأْخُذَ بِأَسْفَلِهَا فَيَجْعَلَهُ أَعْلَاهَا فَثَقُلَتْ عَلَيْهِ فَقَلَبَهَا عَلَيْهِ الْأَيْمَنُ عَلَى الْأَيْسَرِ وَالْأَيْسَرُ عَلَى الْأَيْمَنِ ‏","","",""],[15868,15868,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏يَوْمَ ‏ ‏الْحَرَّةِ ‏ ‏هَلُمَّ إِلَى ‏ ‏ابْنِ حَنْظَلَةَ ‏ ‏يُبَايِعُ ‏ ‏النَّاسَ قَالَ ‏ ‏عَلَامَ يُبَايِعُهُمْ قَالُوا عَلَى الْمَوْتِ قَالَ لَا ‏ ‏أُبَايِعُ ‏ ‏عَلَيْهِ أَحَدًا بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15869,15869,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيِّ ‏ ‏ثُمَّ ‏ ‏الْمَازِنِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ مَرَّتَيْنِ مَرَّتَيْنِ ‏","","",""],[15870,15870,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ الْأَنْصَارِيِّ ‏ ‏ثُمَّ ‏ ‏الْمَازِنِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏وَكَانَ أَحَدَ ‏ ‏رَهْطِهِ ‏ ‏وَكَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ شَهِدَ مَعَهُ ‏ ‏أُحُدًا ‏ ‏قَالَ ‏ ‏قَدْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ اسْتَسْقَى لَنَا أَطَالَ الدُّعَاءَ وَأَكْثَرَ الْمَسْأَلَةَ قَالَ ثُمَّ ‏ ‏تَحَوَّلَ ‏ ‏إِلَى الْقِبْلَةِ ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ فَقَلَبَهُ ظَهْرًا لِبَطْنٍ وَتَحَوَّلَ النَّاسُ مَعَهُ ‏","","",""],[15871,15871,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدٍ الْمَازِنِيَّ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْمُصَلَّى ‏ ‏وَاسْتَسْقَى ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ حِينَ اسْتَقْبَلَ الْقِبْلَةَ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏فِي حَدِيثِهِ وَبَدَأَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ ثُمَّ اسْتَقْبَلَ الْقِبْلَةَ ‏ ‏فَدَعَا ‏","","",""],[15872,15872,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ الْمِصْرِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ بْنِ يَعْقُوبَ الْأَنْصَارِيِّ ‏ ‏أَنَّ ‏ ‏حَبَّانَ بْنَ وَاسِعٍ الْأَنْصَارِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيَّ ‏ ‏يَذْكُرُ أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ ثُمَّ ‏ ‏اسْتَنْشَقَ ‏ ‏ثُمَّ غَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَهُ الْيُمْنَى ثَلَاثًا وَالْأُخْرَى ثَلَاثًا وَمَسَحَ رَأْسَهُ بِمَاءٍ غَيْرِ ‏ ‏فَضْلِ ‏ ‏يَدِهِ وَغَسَلَ رِجْلَيْهِ حَتَّى ‏ ‏أَنْقَاهُمَا ‏","","",""],[15873,15873,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ‏ ‏فَتَوَجَّهَ الْقِبْلَةَ يَدْعُو ‏ ‏وَحَوَّلَ ‏ ‏رِدَاءَهُ ثُمَّ صَلَّى رَكْعَتَيْنِ جَهَرَ فِيهِمَا بِالْقِرَاءَةِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَبَّانُ بْنُ وَاسِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ ‏ ‏بِالْجُحْفَةِ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏حَسَنٍ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏فَمَسَحَ ‏ ‏رَأْسَهُ بِمَاءٍ مِنْ غَيْرِ فَضْلِ يَدِهِ ‏","","",""],[15874,15874,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏أَفَاءَ ‏ ‏اللَّهُ عَلَى رَسُولِهِ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏مَا ‏ ‏أَفَاءَ ‏ ‏قَالَ قَسَمَ فِي النَّاسِ فِي ‏ ‏الْمُؤَلَّفَةِ ‏ ‏قُلُوبُهُمْ وَلَمْ يَقْسِمْ وَلَمْ يُعْطِ ‏ ‏الْأَنْصَارَ ‏ ‏شَيْئًا فَكَأَنَّهُمْ ‏ ‏وَجَدُوا ‏ ‏إِذْ لَمْ يُصِبْهُمْ مَا أَصَابَ النَّاسَ فَخَطَبَهُمْ فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَلَمْ أَجِدْكُمْ ضُلَّالًا فَهَدَاكُمْ اللَّهُ بِي وَكُنْتُمْ مُتَفَرِّقِينَ فَجَمَعَكُمْ اللَّهُ بِي ‏ ‏وَعَالَةً ‏ ‏فَأَغْنَاكُمْ اللَّهُ بِي قَالَ كُلَّمَا قَالَ شَيْئًا قَالُوا اللَّهُ وَرَسُولُهُ ‏ ‏أَمَنُّ ‏ ‏قَالَ مَا يَمْنَعُكُمْ أَنْ تُجِيبُونِي قَالُوا اللَّهُ وَرَسُولُهُ ‏ ‏أَمَنُّ ‏ ‏قَالَ لَوْ شِئْتُمْ لَقُلْتُمْ جِئْتَنَا كَذَا وَكَذَا أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالشَّاةِ وَالْبَعِيرِ وَتَذْهَبُونَ بِرَسُولِ اللَّهِ إِلَى ‏ ‏رِحَالِكُمْ ‏ ‏لَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏لَوْ سَلَكَ النَّاسُ وَادِيًا ‏ ‏وَشِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَ ‏ ‏الْأَنْصَارِ ‏ ‏وَشِعْبَهُمْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعَارٌ ‏ ‏وَالنَّاسُ ‏ ‏دِثَارٌ ‏ ‏وَإِنَّكُمْ سَتَلْقَوْنَ بَعْدِي ‏ ‏أَثَرَةً ‏ ‏فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ ‏","","",""],[15875,15875,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ زَمَنُ ‏ ‏الْحَرَّةِ ‏ ‏أَتَاهُ آتٍ فَقَالَ هَذَا ‏ ‏ابْنُ حَنْظَلَةَ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ‏ ‏هَذَاكَ ‏ ‏ابْنُ حَنْظَلَةَ ‏ ‏يُبَايِعُ ‏ ‏النَّاسَ قَالَ عَلَى أَيِّ شَيْءٍ ‏ ‏يُبَايِعُهُمْ ‏ ‏قَالَ عَلَى الْمَوْتِ قَالَ ‏ ‏لَا ‏ ‏أُبَايِعُ ‏ ‏عَلَى هَذَا أَحَدًا بَعْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15876,15876,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ الْوَاسِطِيَّ الطَّحَّانَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَضْمَضَ ‏ ‏وَاسْتَنْشَقَ ‏ ‏مِنْ ‏ ‏كَفٍّ ‏ ‏وَاحِدٍ ‏","","",""],[15877,15877,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الدَّرَاوَرْدِيُّ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ تَمِيمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى الْمُصَلَّى يَسْتَسْقِي وَعَلَيْهِ ‏ ‏خَمِيصَةٌ ‏ ‏سَوْدَاءُ فَأَخَذَ بِأَسْفَلِهَا لِيَجْعَلَهَا أَعْلَاهَا فَثَقُلَتْ عَلَيْهِ فَقَلَبَهَا عَلَى ‏ ‏عَاتِقِهِ ‏","","",""],[15878,15878,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ هُوَ الْعَطَّارُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏الْمَنْحَرِ ‏ ‏وَرَجُلًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏وَهُوَ ‏ ‏يَقْسِمُ أَضَاحِيَّ فَلَمْ يُصِبْهُ مِنْهَا شَيْءٌ وَلَا صَاحِبَهُ فَحَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ فِي ثَوْبِهِ فَأَعْطَاهُ فَقَسَمَ مِنْهُ عَلَى رِجَالٍ ‏ ‏وَقَلَّمَ ‏ ‏أَظْفَارَهُ فَأَعْطَاهُ صَاحِبَهُ قَالَ فَإِنَّهُ لَعِنْدَنَا ‏ ‏مَخْضُوبٌ ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏ ‏يَعْنِي شَعْرَهُ ‏","","",""],[15879,15879,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏الْمَنْحَرِ ‏ ‏هُوَ وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضَحَايَا فَلَمْ يُصِبْهُ وَلَا صَاحِبَهُ شَيْءٌ فَحَلَقَ رَأْسَهُ فِي ثَوْبِهِ فَأَعْطَاهُ وَقَسَمَ مِنْهُ عَلَى رِجَالٍ ‏ ‏وَقَلَّمَ ‏ ‏أَظْفَارَهُ فَأَعْطَاهُ صَاحِبَهُ فَإِنَّ شَعْرَهُ عِنْدَنَا ‏ ‏مَخْضُوبٌ ‏ ‏بِالْحِنَّاءِ ‏ ‏وَالْكَتَمِ ‏","","",""],[15880,15880,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ أَبُو الْحُسَيْنِ الْعُكْلِيُّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَهْلٍ مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ أُرِيَ الْأَذَانَ ‏ ‏قَالَ ‏ ‏فَجِئْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ ‏ ‏أَلْقِهِ عَلَى ‏ ‏بِلَالٍ ‏ ‏فَأَلْقَيْتُهُ فَأَذَّنَ قَالَ فَأَرَادَ أَنْ يُقِيمَ فَقُلْتُ يَا رَسُولَ اللَّهِ أَنَا رَأَيْتُ أُرِيدُ أَنْ أُقِيمَ قَالَ فَأَقِمْ أَنْتَ فَأَقَامَ هُوَ وَأَذَّنَ ‏ ‏بِلَالٌ ‏","","",""],[15881,15881,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ ‏ ‏قَالَ ‏ ‏لَمَّا أَجْمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَضْرِبَ ‏ ‏بِالنَّاقُوسِ ‏ ‏يَجْمَعُ لِلصَّلَاةِ النَّاسَ وَهُوَ لَهُ كَارِهٌ لِمُوَافَقَتِهِ ‏ ‏النَّصَارَى ‏ ‏طَافَ بِي مِنْ اللَّيْلِ طَائِفٌ وَأَنَا نَائِمٌ رَجُلٌ عَلَيْهِ ثَوْبَانِ أَخْضَرَانِ وَفِي يَدِهِ ‏ ‏نَاقُوسٌ ‏ ‏يَحْمِلُهُ قَالَ فَقُلْتُ لَهُ يَا عَبْدَ اللَّهِ أَتَبِيعُ ‏ ‏النَّاقُوسَ ‏ ‏قَالَ وَمَا تَصْنَعُ بِهِ قُلْتُ ‏ ‏نَدْعُو بِهِ إِلَى الصَّلَاةِ قَالَ أَفَلَا أَدُلُّكَ عَلَى خَيْرٍ مِنْ ذَلِكَ قَالَ فَقُلْتُ بَلَى قَالَ ‏ ‏تَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ قَالَ ثُمَّ اسْتَأْخَرْتُ غَيْرَ بَعِيدٍ قَالَ ثُمَّ تَقُولُ إِذَا أَقَمْتَ الصَّلَاةَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ قَدْ قَامَتْ الصَّلَاةُ قَدْ قَامَتْ الصَّلَاةُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَلَمَّا أَصْبَحْتُ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِمَا رَأَيْتُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ لَرُؤْيَا حَقٌّ إِنْ شَاءَ اللَّهُ ثُمَّ أَمَرَ بِالتَّأْذِينِ فَكَانَ ‏ ‏بِلَالٌ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏يُؤَذِّنُ بِذَلِكَ وَيَدْعُو رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الصَّلَاةِ قَالَ فَجَاءَهُ فَدَعَاهُ ذَاتَ ‏ ‏غَدَاةٍ ‏ ‏إِلَى الْفَجْرِ فَقِيلَ لَهُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَائِمٌ قَالَ فَصَرَخَ ‏ ‏بِلَالٌ ‏ ‏بِأَعْلَى صَوْتِهِ الصَّلَاةُ خَيْرٌ مِنْ النَّوْمِ ‏ ‏قَالَ ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏فَأُدْخِلَتْ هَذِهِ الْكَلِمَةُ فِي التَّأْذِينِ إِلَى صَلَاةِ الْفَجْرِ ‏","","",""],[15882,15882,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاقُوسِ ‏ ‏لِيُضْرَبَ بِهِ لِلنَّاسِ فِي الْجَمْعِ لِلصَّلَاةِ طَافَ بِي وَأَنَا نَائِمٌ رَجُلٌ يَحْمِلُ ‏ ‏نَاقُوسًا ‏ ‏فِي يَدِهِ فَقُلْتُ لَهُ يَا عَبْدَ اللَّهِ أَتَبِيعُ ‏ ‏النَّاقُوسَ ‏ ‏قَالَ مَا تَصْنَعُ بِهِ قَالَ فَقُلْتُ ‏ ‏نَدْعُو بِهِ إِلَى الصَّلَاةِ قَالَ أَفَلَا أَدُلُّكَ عَلَى مَا هُوَ خَيْرٌ مِنْ ذَلِكَ قَالَ فَقُلْتُ لَهُ بَلَى قَالَ ‏ ‏تَقُولُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ حَيَّ عَلَى الْفَلَاحِ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ ثُمَّ اسْتَأْخَرَ غَيْرَ بَعِيدٍ ثُمَّ قَالَ تَقُولُ إِذَا أُقِيمَتْ الصَّلَاةُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ حَيَّ عَلَى الْفَلَاحِ قَدْ قَامَتْ الصَّلَاةُ قَدْ قَامَتْ الصَّلَاةُ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ فَلَمَّا أَصْبَحْتُ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ بِمَا رَأَيْتُ فَقَالَ إِنَّهَا لَرُؤْيَا حَقٌّ إِنْ شَاءَ اللَّهُ فَقُمْ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَأَلْقِ عَلَيْهِ مَا رَأَيْتَ فَلْيُؤَذِّنْ بِهِ فَإِنَّهُ ‏ ‏أَنْدَى ‏ ‏صَوْتًا مِنْكَ قَالَ فَقُمْتُ مَعَ ‏ ‏بِلَالٍ ‏ ‏فَجَعَلْتُ ‏ ‏أُلْقِيهِ عَلَيْهِ وَيُؤَذِّنُ بِهِ قَالَ فَسَمِعَ بِذَلِكَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَهُوَ فِي بَيْتِهِ فَخَرَجَ يَجُرُّ رِدَاءَهُ يَقُولُ وَالَّذِي بَعَثَكَ بِالْحَقِّ لَقَدْ رَأَيْتُ مِثْلَ الَّذِي أُرِيَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلِلَّهِ الْحَمْدُ ‏","","",""],[15883,15883,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ رَبِيعٍ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ضُحًى وَسَلَّمْنَا حِينَ سَلَّمَ ‏ ‏وَأَنَّهُ ‏ ‏يَعْنِي صَلَّى بِهِمْ فِي مَسْجِدٍ عِنْدَهُمْ ‏","","",""],[15884,15884,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فَسُئِلَ ‏ ‏سُفْيَانُ ‏ ‏عَمَّنْ ‏ ‏قَالَ ‏ ‏هُوَ ‏ ‏مَحْمُودٌ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏أَنَّ ‏ ‏عِتْبَانَ بْنَ مَالِكٍ ‏ ‏كَانَ ‏ ‏رَجُلًا مَحْجُوبَ الْبَصَرِ وَأَنَّهُ ذَكَرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّخَلُّفَ عَنْ الصَّلَاةِ قَالَ هَلْ تَسْمَعُ النِّدَاءَ قَالَ نَعَمْ قَالَ فَلَمْ يُرَخِّصْ لَهُ ‏","","",""],[15885,15885,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏أَوْ ‏ ‏الرَّبِيعِ بْنِ مَحْمُودٍ ‏ ‏شَكَّ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي رَجُلٌ ‏ ‏ضَرِيرُ ‏ ‏الْبَصَرِ وَبَيْنِي وَبَيْنَكَ هَذَا الْوَادِي وَالظُّلْمَةُ وَسَأَلْتُهُ أَنْ يَأْتِيَ فَيُصَلِّيَ فِي بَيْتِي فَأَتَّخِذَ مُصَلَّاهُ مُصَلًّى فَوَعَدَنِي أَنْ يَفْعَلَ فَجَاءَ هُوَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏فَتَسَامَعَتْ بِهِ ‏ ‏الْأَنْصَارُ ‏ ‏فَأَتَوْهُ وَتَخَلَّفَ رَجُلٌ مِنْهُمْ يُقَالُ لَهُ ‏ ‏مَالِكُ بْنُ الدُّخْشُنِ ‏ ‏وَكَانَ ‏ ‏يُزَنُّ ‏ ‏بِالنِّفَاقِ فَاحْتَبَسُوا عَلَى طَعَامٍ فَتَذَاكَرُوا بَيْنَهُمْ فَقَالُوا مَا تَخَلَّفَ عَنَّا وَقَدْ عَلِمَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَارَنَا إِلَّا لِنِفَاقِهِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَلَمَّا انْصَرَفَ قَالَ وَيْحَهُ ‏ ‏أَمَا شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ بِهَا مُخْلِصًا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ النَّارَ عَلَى مَنْ شَهِدَ بِهَا ‏","","",""],[15886,15886,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى بْنُ عَبْدِ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ السُّيُولَ تَحُولُ بَيْنِي وَبَيْنَ مَسْجِدِ قَوْمِي فَأُحِبُّ أَنْ تَأْتِيَنِي فَتُصَلِّيَ فِي مَكَانٍ فِي بَيْتِي أَتَّخِذُهُ مَسْجِدًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَنَفْعَلُ قَالَ فَلَمَّا أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَدَا ‏ ‏عَلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَاسْتَتْبَعَهُ فَلَمَّا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَيْنَ تُرِيدُ فَأَشَرْتُ لَهُ إِلَى نَاحِيَةٍ مِنْ الْبَيْتِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصُفِفْنَا خَلْفَهُ فَصَلَّى بِنَا رَكْعَتَيْنِ وَحَبَسْنَاهُ عَلَى ‏ ‏خَزِيرٍ ‏ ‏صَنَعْنَاهُ فَسَمِعَ أَهْلُ الدَّارِ ‏ ‏يَعْنِي أَهْلَ الْقَرْيَةِ ‏ ‏فَجَعَلُوا ‏ ‏يَثُوبُونَ ‏ ‏فَامْتَلَأَ الْبَيْتُ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَيْنَ ‏ ‏مَالِكُ بْنُ الدُّخْشُمِ ‏ ‏فَقَالَ رَجُلٌ ذَاكَ مِنْ الْمُنَافِقِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُهُ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِهَا وَجْهَ اللَّهِ قَالَ أَمَّا نَحْنُ ‏ ‏فَنَرَى وَجْهَهُ وَحَدِيثَهُ إِلَى الْمُنَافِقِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُهُ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ بَلَى يَا رَسُولَ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَئِنْ ‏ ‏وَافَى ‏ ‏عَبْدٌ يَوْمَ الْقِيَامَةِ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ يَبْتَغِي بِذَلِكَ وَجْهَ اللَّهِ إِلَّا حُرِّمَ عَلَى النَّارِ ‏ ‏فَقَالَ ‏ ‏مَحْمُودٌ ‏ ‏فَحَدَّثْتُ بِذَلِكَ قَوْمًا فِيهِمْ ‏ ‏أَبُو أَيُّوبَ ‏ ‏قَالَ مَا أَظُنُّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَذَا قَالَ فَقُلْتُ لَئِنْ رَجَعْتُ ‏ ‏وَعِتْبَانُ ‏ ‏حَيٌّ لَأَسْأَلَنَّهُ فَقَدِمْتُ وَهُوَ أَعْمَى وَهُوَ إِمَامُ قَوْمِهِ فَسَأَلْتُهُ ‏ ‏فَحَدَّثَنِي كَمَا حَدَّثَنِي أَوَّلَ مَرَّةٍ وَكَانَ ‏ ‏عِتْبَانُ ‏ ‏بَدْرِيًّا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مَحْمُودِ بْنِ الرَّبِيعِ ‏ ‏عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي قَدْ ‏ ‏أَنْكَرْتُ ‏ ‏بَصَرِي فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ ‏ ‏مَالِكُ بْنُ الدُّخْشُنِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏الدُّخَيْشِنِ ‏ ‏وَقَالَ حُرِّمَ عَلَى النَّارِ وَلَمْ يَقُلْ كَانَ بَدْرِيًّا ‏","","",""],[15887,15887,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدِ بْنِ جُدْعَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَدِمَ أَبِي مِنْ ‏ ‏الشَّامِ ‏ ‏وَافِدًا وَأَنَا مَعَهُ فَلَقِينَا ‏ ‏مَحْمُودَ بْنَ الرَّبِيعِ ‏ ‏فَحَدَّثَ أَبِي حَدِيثًا عَنْ ‏ ‏عِتْبَانَ بْنِ مَالِكٍ ‏ ‏قَالَ أَبِي أَيْ بُنَيَّ احْفَظْ هَذَا الْحَدِيثَ فَإِنَّهُ مِنْ كُنُوزِ الْحَدِيثِ فَلَمَّا ‏ ‏قَفَلْنَا ‏ ‏انْصَرَفْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَسَأَلْنَا عَنْهُ فَإِذَا هُوَ حَيٌّ وَإِذَا شَيْخٌ أَعْمَى قَالَ فَسَأَلْنَاهُ عَنْ الْحَدِيثِ فَقَالَ نَعَمْ ذَهَبَ بَصَرِي عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ذَهَبَ بَصَرِي وَلَا أَسْتَطِيعُ الصَّلَاةَ خَلْفَكَ فَلَوْ ‏ ‏بَوَّأْتَ ‏ ‏فِي دَارِي مَسْجِدًا فَصَلَّيْتُ فِيهِ فَأَتَّخِذُهُ مُصَلًّى قَالَ نَعَمْ فَإِنِّي ‏ ‏غَادٍ ‏ ‏عَلَيْكَ غَدًا قَالَ فَلَمَّا صَلَّى مِنْ الْغَدِ الْتَفَتَ إِلَيْهِ فَقَامَ حَتَّى أَتَاهُ فَقَالَ يَا ‏ ‏عِتْبَانُ ‏ ‏أَيْنَ تُحِبُّ أَنْ ‏ ‏أُبَوِّئَ ‏ ‏لَكَ فَوَصَفَ لَهُ مَكَانًا ‏ ‏فَبَوَّأَ ‏ ‏لَهُ وَصَلَّى فِيهِ ثُمَّ ‏ ‏حَبَسَ ‏ ‏أَوْ جَلَسَ ‏ ‏وَبَلَغَ مَنْ حَوْلَنَا مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءُوا حَتَّى مُلِئَتْ عَلَيْنَا الدَّارُ فَذَكَرُوا الْمُنَافِقِينَ وَمَا يَلْقُونَ مِنْ أَذَاهُمْ وَشَرِّهِمْ حَتَّى صَيَّرُوا أَمْرَهُمْ إِلَى رَجُلٍ مِنْهُمْ يُقَالُ لَهُ ‏ ‏مَالِكُ بْنُ الدُّخْشُمِ ‏ ‏وَقَالُوا مِنْ حَالِهِ وَمِنْ حَالِهِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاكِتٌ فَلَمَّا أَكْثَرُوا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَلَمَّا كَانَ فِي الثَّالِثَةِ قَالُوا إِنَّهُ لَيَقُولُهُ قَالَ وَالَّذِي بَعَثَنِي بِالْحَقِّ لَئِنْ قَالَهَا صَادِقًا مِنْ قَلْبِهِ لَا تَأْكُلُهُ النَّارُ أَبَدًا قَالُوا فَمَا فَرِحُوا بِشَيْءٍ قَطُّ كَفَرَحِهِمْ بِمَا قَالَ ‏","","",""],[15888,15888,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْبَرَاءِ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏أَبِي بُرْدَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّا ‏ ‏عَجَّلْنَا ‏ ‏شَاةَ لَحْمٍ لَنَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَبْلَ الصَّلَاةِ قُلْتُ نَعَمْ قَالَ تِلْكَ شَاةُ لَحْمٍ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ عِنْدَنَا ‏ ‏عَنَاقًا ‏ ‏جَذَعَةً ‏ ‏هِيَ أَحَبُّ إِلَيَّ مِنْ ‏ ‏مُسِنَّةٍ ‏ ‏قَالَ ‏ ‏تُجْزِئُ ‏ ‏عَنْهُ وَلَا ‏ ‏تُجْزِئُ ‏ ‏عَنْ أَحَدٍ بَعْدَهُ ‏","","",""],[15889,15889,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15890,15890,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏أَنَّ ‏ ‏بُكَيْرًا ‏ ‏حَدَّثَهُ قَالَ ‏ ‏بَيْنَمَا أَنَا جَالِسٌ عِنْدَ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏إِذْ جَاءَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏يُحَدِّثُ ‏ ‏سُلَيْمَانَ ‏ ‏ثُمَّ أَقْبَلَ عَلَيْنَا ‏ ‏سُلَيْمَانُ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جَابِرٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا بُرْدَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَجْلِدُوا فَوْقَ عَشَرَةَ ‏ ‏أَسْوَاطٍ ‏ ‏إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏ ‏كَذَا قَالَ لَنَا فِيهِ قَالَ أَبِي وَأَنَا أَذْهَبُ إِلَيْهِ ‏ ‏يَعْنِي الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏","","",""],[15891,15891,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا بُرْدَةَ بْنَ نِيَارٍ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَجْلِدُوا فَوْقَ عَشَرَةَ ‏ ‏أَسْوَاطٍ ‏ ‏إِلَّا فِي ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15892,15892,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو الْكَلْبِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏جُمَيْعٍ ‏ ‏أَوْ ‏ ‏أَبِي جُمَيْعٍ ‏ ‏عَنْ ‏ ‏خَالِهِ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى طَعَامًا فَأَدْخَلَ يَدَهُ فِيهِ فَرَأَى غَيْرَ ذَلِكَ فَقَالَ ‏ ‏لَيْسَ مِنَّا مَنْ غَشَّنَا ‏","","",""],[15893,15893,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُشَيْرُ بْنُ يَسَارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي حَارِثَةَ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏شَهِدْتُ الْعِيدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَخَالَفَتْ امْرَأَتِي حَيْثُ ‏ ‏غَدَوْتُ ‏ ‏إِلَى الصَّلَاةِ إِلَى أُضْحِيَّتِي فَذَبَحَتْهَا وَصَنَعَتْ مِنْهَا طَعَامًا قَالَ فَلَمَّا صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْصَرَفْتُ إِلَيْهَا جَاءَتْنِي بِطَعَامٍ قَدْ فُرِغَ مِنْهُ فَقُلْتُ أَنَّى هَذَا قَالَتْ أُضْحِيَّتُكَ ذَبَحْنَاهَا وَصَنَعْنَا لَكَ مِنْهَا طَعَامًا ‏ ‏لِتَغَدَّى إِذَا جِئْتَ قَالَ فَقُلْتُ لَهَا وَاللَّهِ لَقَدْ خَشِيتُ أَنْ يَكُونَ هَذَا لَا يَنْبَغِي قَالَ فَجِئْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ ‏ ‏لَيْسَتْ بِشَيْءٍ مَنْ ذَبَحَ قَبْلَ أَنْ نَفْرُغَ مِنْ ‏ ‏نُسُكِنَا ‏ ‏فَلَيْسَ بِشَيْءٍ ‏ ‏فَضَحِّ ‏ ‏قَالَ فَالْتَمَسْتُ ‏ ‏مُسِنَّةً ‏ ‏فَلَمْ أَجِدْهَا قَالَ فَجِئْتُهُ فَقُلْتُ وَاللَّهِ يَا رَسُولَ اللَّهِ لَقَدْ الْتَمَسْتُ ‏ ‏مُسِنَّةً ‏ ‏فَمَا وَجَدْتُهَا قَالَ فَالْتَمِسْ ‏ ‏جَذَعًا ‏ ‏مِنْ الضَّأْنِ ‏ ‏فَضَحِّ ‏ ‏بِهِ قَالَ فَرَخَّصَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْجَذَعِ ‏ ‏مِنْ الضَّأْنِ فَضَحَّى بِهِ حَيْثُ لَمْ يَجِدْ ‏ ‏الْمُسِنَّةَ ‏","","",""],[15894,15894,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ الْمُقْرِئُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ بْنِ نِيَارٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يُجْلَدُ فَوْقَ عَشَرَةِ ‏ ‏أَسْوَاطٍ ‏ ‏فِيمَا دُونَ ‏ ‏حَدٍّ ‏ ‏مِنْ ‏ ‏حُدُودِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ ‏ ‏كَذَا قَالَ لَنَا لَمْ يَقُلْ عَنْ أَبِيهِ ‏","","",""],[15895,15895,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَارَزْتُ رَجُلًا فَقَتَلْتُهُ ‏ ‏فَنَفَّلَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَبَهُ ‏","","",""],[15896,15896,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏رَجُلًا ‏ ‏يَأْكُلُ بِشِمَالِهِ فَقَالَ ‏ ‏كُلْ بِيَمِينِكَ ‏ ‏فَقَالَ لَا أَسْتَطِيعُ فَقَالَ لَا اسْتَطَعْتَ قَالَ فَمَا رَجَعَتْ إِلَيْهِ ‏","","",""],[15897,15897,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَتَلْتُ رَجُلًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ هَذَا فَقَالُوا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏فَقَالَ لَهُ ‏ ‏سَلَبُهُ ‏","","",""],[15898,15898,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامٌ يُسَمَّى ‏ ‏رَبَاحًا ‏","","",""],[15899,15899,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْلَى بْنُ الْحَارِثِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِيَاسَ بْنَ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ نَرْجِعُ فَلَا نَجِدُ ‏ ‏لِلْحِيطَانِ ‏ ‏فَيْئًا ‏ ‏يُسْتَظَلُّ فِيهِ ‏","","",""],[15900,15900,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَيَّتْنَا ‏ ‏هَوَازِنَ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏وَكَانَ ‏ ‏أَمَّرَهُ عَلَيْنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15901,15901,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏شِعَارُنَا ‏ ‏لَيْلَةَ بَيَّتْنَا فِي ‏ ‏هَوَازِنَ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏وَأَمَّرَهُ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِتْ أَمِتْ وَقَتَّلْتُ بِيَدَيَّ ‏ ‏لَيْلَتَئِذٍ ‏ ‏سَبْعَةً أَهْلَ أَبْيَاتٍ ‏","","",""],[15902,15902,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ الْيَمَامِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ لِرَجُلٍ يُقَالُ لَهُ ‏ ‏بُسْرُ ‏ ‏ابْنُ رَاعِي ‏ ‏الْعِيرِ ‏ ‏أَبْصَرَهُ يَأْكُلُ بِشِمَالِهِ فَقَالَ ‏ ‏كُلْ بِيَمِينِكَ فَقَالَ لَا أَسْتَطِيعُ فَقَالَ لَا اسْتَطَعْتَ قَالَ فَمَا وَصَلَتْ يَمِينُهُ إِلَى فَمِهِ بَعْدُ ‏ ‏و قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فِي حَدِيثِهِ ‏ ‏ابْنُ رَاعِي ‏ ‏الْعِيرِ ‏ ‏مِنْ ‏ ‏أَشْجَعَ ‏","","",""],[15903,15903,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏سَلَّ ‏ ‏عَلَيْنَا السَّيْفَ فَلَيْسَ مِنَّا ‏","","",""],[15904,15904,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏كُنْتُ قَاعِدًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَطَسَ رَجُلٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُكَ اللَّهُ ثُمَّ عَطَسَ أُخْرَى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلُ مَزْكُومٌ ‏","","",""],[15905,15905,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي قُحَافَةَ ‏ ‏وَأَمَّرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْنَا قَالَ غَزَوْنَا ‏ ‏فَزَارَةَ ‏ ‏فَلَمَّا ‏ ‏دَنَوْنَا ‏ ‏مِنْ الْمَاءِ أَمَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَعَرَّسْنَا ‏ ‏قَالَ فَلَمَّا صَلَّيْنَا الصُّبْحَ أَمَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَشَنَنَّا ‏ ‏الْغَارَةَ ‏ ‏فَقَتَلْنَا عَلَى الْمَاءِ مَنْ قَتَلْنَا قَالَ ‏ ‏سَلَمَةُ ‏ ‏ثُمَّ نَظَرْتُ إِلَى ‏ ‏عُنُقٍ ‏ ‏مِنْ النَّاسِ فِيهِ الذُّرِّيَّةُ وَالنِّسَاءُ نَحْوَ الْجَبَلِ وَأَنَا ‏ ‏أَعْدُو ‏ ‏فِي آثَارِهِمْ فَخَشِيتُ أَنْ يَسْبِقُونِي إِلَى الْجَبَلِ فَرَمَيْتُ بِسَهْمٍ فَوَقَعَ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ قَالَ فَجِئْتُ بِهِمْ أَسُوقُهُمْ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَتَّى أَتَيْتُهُ عَلَى الْمَاءِ وَفِيهِمْ امْرَأَةٌ مِنْ ‏ ‏فَزَارَةَ ‏ ‏عَلَيْهَا ‏ ‏قَشْعٌ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏وَمَعَهَا ابْنَةٌ لَهَا مِنْ أَحْسَنِ ‏ ‏الْعَرَبِ ‏ ‏قَالَ ‏ ‏فَنَفَّلَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏ابْنَتَهَا قَالَ فَمَا كَشَفْتُ لَهَا ثَوْبًا حَتَّى قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏ثُمَّ ‏ ‏بِتُّ ‏ ‏فَلَمْ أَكْشِفْ لَهَا ثَوْبًا قَالَ فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السُّوقِ فَقَالَ لِي يَا ‏ ‏سَلَمَةُ ‏ ‏هَبْ لِي الْمَرْأَةَ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ وَاللَّهِ لَقَدْ أَعْجَبَتْنِي وَمَا كَشَفْتُ لَهَا ثَوْبًا قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَتَرَكَنِي حَتَّى إِذَا كَانَ مِنْ الْغَدِ لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السُّوقِ فَقَالَ يَا ‏ ‏سَلَمَةُ ‏ ‏هَبْ لِي الْمَرْأَةَ لِلَّهِ أَبُوكَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ وَاللَّهِ أَعْجَبَتْنِي مَا كَشَفْتُ لَهَا ثَوْبًا وَهِيَ لَكَ يَا رَسُولَ اللَّهِ قَالَ فَبَعَثَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏وَفِي أَيْدِيهِمْ أُسَارَى مِنْ الْمُسْلِمِينَ فَفَدَاهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتِلْكَ الْمَرْأَةِ ‏","","",""],[15906,15906,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏سَلَمَةَ بْنَ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏خَيْبَرَ ‏ ‏قَاتَلَ أَخِي قِتَالًا شَدِيدًا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَارْتَدَّ عَلَيْهِ سَيْفُهُ ‏ ‏فَقَتَلَهُ فَقَالَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ذَلِكَ وَشَكُّوا فِيهِ رَجُلٌ مَاتَ بِسِلَاحِهِ شَكُّوا فِي بَعْضِ أَمْرِهِ قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَقَفَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏خَيْبَرَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَتَأْذَنُ لِي أَنْ ‏ ‏أَرْجُزَ ‏ ‏بِكَ فَأَذِنَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏عُمَرُ ‏ ‏اعْلَمْ مَا تَقُولُ قَالَ فَقُلْتُ ‏ ‏وَاللَّهِ لَوْلَا اللَّهُ مَا اهْتَدَيْنَا ‏ ‏وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقْتَ ‏ ‏فَأَنْزِلَنْ ‏ ‏سَكِينَةً ‏ ‏عَلَيْنَا ‏ ‏وَثَبِّتْ الْأَقْدَامَ إِنْ لَاقَيْنَا ‏ ‏وَالْمُشْرِكُونَ قَدْ ‏ ‏بَغَوْا ‏ ‏عَلَيْنَا ‏ ‏فَلَمَّا قَضَيْتُ ‏ ‏رَجَزِي ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ هَذَا قُلْتُ أَخِي قَالَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُهُ اللَّهُ فَقُلْتُ يَا رَسُولَ اللَّهِ وَاللَّهِ ‏ ‏إِنَّ نَاسًا ‏ ‏لَيَهَابُونَ ‏ ‏أَنْ يُصَلُّوا عَلَيْهِ وَيَقُولُونَ رَجُلٌ مَاتَ بِسِلَاحِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَاتَ ‏ ‏جَاهِدًا ‏ ‏مُجَاهِدًا ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏ثُمَّ سَأَلْتُ ‏ ‏ابْنَ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏أَبِيهِ ‏ ‏مِثْلَ الَّذِي حَدَّثَنِي عَنْهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏غَيْرَ أَنَّ ‏ ‏ابْنَ سَلَمَةَ ‏ ‏قَالَ قَالَ مَعَ ذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَهَابُونَ ‏ ‏الصَّلَاةَ عَلَيْهِ كَذَبُوا مَاتَ ‏ ‏جَاهِدًا ‏ ‏مُجَاهِدًا فَلَهُ أَجْرُهُ مَرَّتَيْنِ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِإِصْبَعَيْهِ ‏","","",""],[15907,15907,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏حَسَنِ بْنِ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَسَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏كُنَّا فِي ‏ ‏غَزَاةٍ ‏ ‏فَجَاءَنَا رَسُولُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اسْتَمْتِعُوا ‏","","",""],[15908,15908,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ الْيَمَامِيِّ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فِي ‏ ‏غَزَاةِ ‏ ‏هَوَازِنَ ‏ ‏فَنَفَّلَنِي ‏ ‏جَارِيَةً ‏ ‏فَاسْتَوْهَبَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَ بِهَا إِلَى ‏ ‏مَكَّةَ ‏ ‏فَفَدَى بِهَا أُنَاسًا مِنْ الْمُسْلِمِينَ ‏","","",""],[15909,15909,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[15910,15910,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ رَجُلًا مِنْ ‏ ‏أَسْلَمَ ‏ ‏أَنْ ‏ ‏يُؤَذِّنَ ‏ ‏فِي النَّاسِ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏مَنْ كَانَ صَائِمًا فَلْيُتِمَّ صَوْمَهُ وَمَنْ كَانَ أَكَلَ فَلَا يَأْكُلْ شَيْئًا وَلِيُتِمَّ صَوْمَهُ ‏","","",""],[15911,15911,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏أَنَّهُ ‏ ‏اسْتَأْذَنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَدْوِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[15912,15912,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ النَّاسِ فِي ‏ ‏الْحُدَيْبِيَةِ ‏ ‏ثُمَّ قَعَدْتُ ‏ ‏مُتَنَحِّيًا ‏ ‏فَلَمَّا تَفَرَّقَ النَّاسُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏ابْنَ الْأَكْوَعِ ‏ ‏أَلَا ‏ ‏تُبَايِعُ ‏ ‏قَالَ قُلْتُ قَدْ ‏ ‏بَايَعْتُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ أَيْضًا ‏ ‏قُلْتُ عَلَامَ ‏ ‏بَايَعْتُمْ ‏ ‏قَالَ ‏ ‏عَلَى الْمَوْتِ ‏","","",""],[15913,15913,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُتِيَ بِجِنَازَةٍ فَقَالَ ‏ ‏هَلْ تَرَكَ مِنْ دَيْنٍ قَالُوا لَا قَالَ هَلْ تَرَكَ مِنْ شَيْءٍ قَالُوا لَا قَالَ فَصَلَّى عَلَيْهِ ثُمَّ أُتِيَ بِأُخْرَى فَقَالَ هَلْ تَرَكَ مِنْ دَيْنٍ قَالُوا لَا قَالَ هَلْ تَرَكَ مِنْ شَيْءٍ قَالُوا نَعَمْ ثَلَاثَ دَنَانِيرَ قَالَ فَقَالَ بِإِصْبَعِهِ ثَلَاثَ كَيَّاتٍ قَالَ ثُمَّ أُتِيَ بِالثَّالِثَةِ فَقَالَ هَلْ تَرَكَ مِنْ دَيْنٍ قَالُوا نَعَمْ قَالَ هَلْ تَرَكَ مِنْ شَيْءٍ قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَيَّ دَيْنُهُ يَا رَسُولَ اللَّهِ قَالَ فَصَلَّى عَلَيْهِ ‏","","",""],[15914,15914,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَامِرٌ ‏ ‏رَجُلًا شَاعِرًا فَنَزَلَ ‏ ‏يَحْدُو ‏ ‏قَالَ وَيَقُولُ ‏ ‏اللَّهُمَّ لَوْلَا أَنْتَ مَا اهْتَدَيْنَا ‏ ‏وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا ‏ ‏فَاغْفِرْ فِدًى لَكَ مَا أَتَيْنَا ‏ ‏وَثَبِّتْ الْأَقْدَامَ إِنْ لَاقَيْنَا ‏ ‏وَأَلْقِيَنْ ‏ ‏سَكِينَةً ‏ ‏عَلَيْنَا ‏ ‏إِنَّا إِذَا صِيحَ بِنَا أَتَيْنَا ‏ ‏وَبِالصِّيَاحِ ‏ ‏عَوَّلُوا ‏ ‏عَلَيْنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَذَا ‏ ‏الْحَادِي ‏ ‏قَالُوا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏قَالَ يَرْحَمُهُ اللَّهُ قَالَ فَقَالَ رَجُلٌ وَجَبَتْ يَا رَسُولَ اللَّهِ لَوْلَا ‏ ‏أَمْتَعْتَنَا ‏ ‏بِهِ قَالَ فَأُصِيبَ ذَهَبَ يَضْرِبُ رَجُلًا يَهُودِيًّا فَأَصَابَ ‏ ‏ذُبَابُ ‏ ‏السَّيْفِ عَيْنَ رُكْبَتِهِ فَقَالَ النَّاسُ ‏ ‏حَبِطَ ‏ ‏عَمَلُهُ قَتَلَ نَفْسَهُ قَالَ فَجِئْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَنْ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَهُوَ فِي ‏ ‏الْمَسْجِدِ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ يَزْعُمُونَ أَنَّ ‏ ‏عَامِرًا ‏ ‏حَبِطَ ‏ ‏عَمَلُهُ قَالَ وَمَنْ يَقُولُهُ قَالَ قُلْتُ رِجَالٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِنْهُمْ فُلَانٌ وَفُلَانٌ قَالَ كَذَبَ مَنْ قَالَهُ ‏ ‏إِنَّ لَهُ لَأَجْرَيْنِ بِإِصْبَعَيْهِ وَإِنَّهُ لَجَاهِدٌ مُجَاهِدٌ وَقَلَّ عَرَبِيٌّ مَا مَشَى بِهَا يُرِيدُكَ عَلَيْهِ ‏","","",""],[15915,15915,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ مُنَادِيَهُ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏أَنَّ مَنْ كَانَ ‏ ‏اصْطَبَحَ ‏ ‏فَلْيُمْسِكْ وَمَنْ لَمْ يَكُنْ ‏ ‏اصْطَبَحَ ‏ ‏فَلْيُتِمَّ صَوْمَهُ ‏","","",""],[15916,15916,"","","‏ ‏قَالَ ‏ ‏صَفْوَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمْنَا ‏ ‏خَيْبَرَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِيرَانًا تُوقَدُ فَقَالَ ‏ ‏عَلَامَ تُوقَدُ هَذِهِ النِّيرَانُ قَالُوا عَلَى لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ قَالَ كَسِّرُوا الْقُدُورَ ‏ ‏وَأَهْرِيقُوا ‏ ‏مَا فِيهَا قَالَ فَقَامَ رَجُلٌ مِنْ الْقَوْمِ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَنُهْرِيقُ ‏ ‏مَا فِيهَا وَنَغْسِلُهَا قَالَ أَوَذَاكَ ‏","","",""],[15917,15917,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّهُ أَخْبَرَهُ قَالَ ‏ ‏خَرَجْتُ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏ذَاهِبًا نَحْوَ ‏ ‏الْغَابَةِ ‏ ‏حَتَّى إِذَا كُنْتُ ‏ ‏بِثَنِيَّةِ الْغَابَةِ ‏ ‏لَقِيَنِي غُلَامٌ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ قُلْتُ ‏ ‏وَيْحَكَ ‏ ‏مَا لَكَ قَالَ أُخِذَتْ ‏ ‏لِقَاحُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ مَنْ أَخَذَهَا قَالَ ‏ ‏غَطَفَانُ ‏ ‏وفَزَارَةُ ‏ ‏قَالَ فَصَرَخْتُ ثَلَاثَ صَرَخَاتٍ أَسْمَعَتْ مَنْ بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏يَا ‏ ‏صَبَاحَاهْ يَا ‏ ‏صَبَاحَاهْ ثُمَّ انْدَفَعْتُ حَتَّى أَلْقَاهُمْ وَقَدْ أَخَذُوهَا قَالَ فَجَعَلْتُ أَرْمِيهِمْ وَأَقُولُ ‏ ‏أَنَا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏وَالْيَوْمُ يَوْمٌ أَقْرَعُ ‏ ‏قَالَ فَاسْتَنْقَذْتُهَا مِنْهُمْ قَبْلَ أَنْ يَشْرَبُوا فَأَقْبَلْتُ بِهَا أَسُوقُهَا فَلَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ الْقَوْمَ عِطَاشٌ وَإِنِّي ‏ ‏أَعْجَلْتُهُمْ ‏ ‏قَبْلَ أَنْ يَشْرَبُوا فَاذْهَبْ فِي ‏ ‏أَثَرِهِمْ ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ الْأَكْوَعِ ‏ ‏مَلَكْتَ ‏ ‏فَأَسْجِحْ ‏ ‏إِنَّ الْقَوْمَ ‏ ‏يُقْرَوْنَ ‏ ‏فِي قَوْمِهِمْ ‏","","",""],[15918,15918,"","","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَثَرَ ‏ ‏ضَرْبَةٍ فِي سَاقِ ‏ ‏سَلَمَةَ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا مُسْلِمٍ ‏ ‏مَا هَذِهِ الضَّرْبَةُ قَالَ هَذِهِ ضَرْبَةٌ أُصِبْتُهَا يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏قَالَ يَوْمَ أُصِبْتُهَا قَالَ النَّاسُ أُصِيبَ ‏ ‏سَلَمَةُ ‏ ‏فَأُتِيَ بِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَفَثَ ‏ ‏فِيهِ ثَلَاثَ ‏ ‏نَفَثَاتٍ ‏ ‏فَمَا ‏ ‏اشْتَكَيْتُهَا ‏ ‏حَتَّى السَّاعَةِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمٌ يَعْنِي ابْنَ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَلَمَةَ بْنَ الْأَكْوَعِ ‏ ‏يَقُولُ ‏ ‏خَرَجْتُ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏مَكِّيٍّ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏وَالْيَوْمُ يَوْمُ الرُّضَّعِ ‏ ‏وَزَادَ فِيهِ ‏ ‏وَأَرْدَفَنِي ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رَاحِلَتِهِ ‏","","",""],[15919,15919,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ آتِي مَعَ ‏ ‏سَلَمَةَ ‏ ‏الْمَسْجِدَ فَيُصَلِّي مَعَ ‏ ‏الْأُسْطُوَانَةِ ‏ ‏الَّتِي عِنْدَ الْمُصْحَفِ فَقُلْتُ يَا ‏ ‏أَبَا مُسْلِمٍ ‏ ‏أَرَاكَ ‏ ‏تَتَحَرَّى ‏ ‏الصَّلَاةَ عِنْدَ هَذِهِ ‏ ‏الْأُسْطُوَانَةِ ‏ ‏قَالَ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَرَّى ‏ ‏الصَّلَاةَ عِنْدَهَا ‏","","",""],[15920,15920,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ رَاشِدٍ الْيَمَامِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا أَمَا وَاللَّهِ مَا أَنَا قُلْتُهُ وَلَكِنَّ اللَّهَ قَالَهُ ‏","","",""],[15921,15921,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏قَدِمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحُدَيْبِيَةَ ‏ ‏وَنَحْنُ أَرْبَعَ عَشْرَةَ مِائَةً وَعَلَيْهَا خَمْسُونَ شَاةً لَا ‏ ‏تُرْوِيهَا فَقَعَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏جَبَاهَا ‏ ‏فَإِمَّا ‏ ‏دَعَا ‏ ‏وَإِمَّا ‏ ‏بَسَقَ ‏ ‏فَجَاشَتْ ‏ ‏فَسَقَيْنَا وَاسْتَقَيْنَا قَالَ ثُمَّ إِنَّ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا بِالْبَيْعَةِ فِي ‏ ‏أَصْلِ ‏ ‏الشَّجَرَةِ فَبَايَعْتُهُ أَوَّلَ النَّاسِ وَبَايَعَ وَبَايَعَ حَتَّى إِذَا كَانَ فِي وَسَطٍ مِنْ النَّاسِ قَالَ يَا ‏ ‏سَلَمَةُ ‏ ‏بَايِعْنِي قَالَ قَدْ بَايَعْتُكَ فِي أَوَّلِ النَّاسِ يَا رَسُولَ اللَّهِ قَالَ وَأَيْضًا فَبَايِعْ وَرَآنِي أَعْزَلًا فَأَعْطَانِي ‏ ‏حَجَفَةً ‏ ‏أَوْ ‏ ‏دَرَقَةً ‏ ‏ثُمَّ بَايَعَ وَبَايَعَ حَتَّى إِذَا كَانَ فِي آخِرِ النَّاسِ قَالَ أَلَا تُبَايِعُنِي قَالَ قُلْتُ يَا رَسُولَ اللَّهِ قَدْ بَايَعْتُ أَوَّلَ النَّاسِ وَأَوْسَطَهُمْ وَآخِرَهُمْ قَالَ وَأَيْضًا فَبَايِعْ فَبَايَعْتُهُ ثُمَّ قَالَ أَيْنَ ‏ ‏دَرَقَتُكَ ‏ ‏أَوْ ‏ ‏حَجَفَتُكَ ‏ ‏الَّتِي أَعْطَيْتُكَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ لَقِيَنِي عَمِّي ‏ ‏عَامِرٌ ‏ ‏أَعْزَلًا فَأَعْطَيْتُهُ إِيَّاهَا قَالَ فَقَالَ إِنَّكَ كَالَّذِي قَالَ اللَّهُمَّ ‏ ‏ابْغِنِي ‏ ‏حَبِيبًا هُوَ أَحَبُّ إِلَيَّ مِنْ نَفْسِي وَضَحِكَ ثُمَّ إِنَّ الْمُشْرِكِينَ رَاسَلُونَا الصُّلْحَ حَتَّى مَشَى بَعْضُنَا إِلَى بَعْضٍ قَالَ وَكُنْتُ ‏ ‏تَبِيعًا ‏ ‏لِطَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏أَحُسُّ فَرَسَهُ ‏ ‏وَأَسْقِيهِ وَآكُلُ مِنْ طَعَامِهِ وَتَرَكْتُ أَهْلِي وَمَالِي مُهَاجِرًا إِلَى اللَّهِ وَرَسُولِهِ فَلَمَّا اصْطَلَحْنَا نَحْنُ وَأَهْلُ ‏ ‏مَكَّةَ ‏ ‏وَاخْتَلَطَ بَعْضُنَا بِبَعْضٍ أَتَيْتُ الشَّجَرَةَ ‏ ‏فَكَسَحْتُ ‏ ‏شَوْكَهَا وَاضْطَجَعْتُ فِي ظِلِّهَا فَأَتَانِي أَرْبَعَةٌ مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَجَعَلُوا وَهُمْ مُشْرِكُونَ يَقَعُونَ فِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَحَوَّلْتُ عَنْهُمْ إِلَى شَجَرَةٍ أُخْرَى وَعَلَّقُوا سِلَاحَهُمْ وَاضْطَجَعُوا فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ نَادَى مُنَادٍ مِنْ أَسْفَلِ ‏ ‏الْوَادِي ‏ ‏يَا آلَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏قُتِلَ ‏ ‏ابْنُ زُنَيْمٍ ‏ ‏فَاخْتَرَطْتُ ‏ ‏سَيْفِي فَشَدَدْتُ عَلَى الْأَرْبَعَةِ فَأَخَذْتُ سِلَاحَهُمْ فَجَعَلْتُهُ ‏ ‏ضِغْثًا ‏ ‏ثُمَّ قُلْتُ وَالَّذِي أَكْرَمَ ‏ ‏مُحَمَّدًا ‏ ‏لَا يَرْفَعُ رَجُلٌ مِنْكُمْ رَأْسَهُ إِلَّا ضَرَبْتُ الَّذِي ‏ ‏يَعْنِي فِيهِ عَيْنَاهُ ‏ ‏فَجِئْتُ أَسُوقُهُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَاءَ عَمِّي ‏ ‏عَامِرٌ ‏ ‏بِابْنِ مِكْرَزٍ ‏ ‏يَقُودُ بِهِ فَرَسَهُ يَقُودُ سَبْعِينَ حَتَّى وَقَفْنَاهُمْ فَنَظَرَ إِلَيْهِمْ فَقَالَ دَعُوهُمْ يَكُونُ لَهُمْ ‏ ‏بُدُوُّ ‏ ‏الْفُجُورِ وَعَفَا عَنْهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُنْزِلَتْ ‏ { ‏وَهُوَ الَّذِي كَفَّ أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ ‏} ‏ثُمَّ رَجَعْنَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَنَزَلْنَا مَنْزِلًا يُقَالُ لَهُ ‏ ‏لَحْيُ جَمَلٍ ‏ ‏فَاسْتَغْفَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِمَنْ ‏ ‏رَقِيَ ‏ ‏الْجَبَلَ فِي تِلْكَ اللَّيْلَةِ كَانَ ‏ ‏طَلِيعَةً ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ ‏ ‏فَرَقِيتُ ‏ ‏تِلْكَ اللَّيْلَةِ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثَةً ‏ ‏ثُمَّ قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏وَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِظَهْرِهِ ‏ ‏مَعَ غُلَامِهِ ‏ ‏رَبَاحٍ ‏ ‏وَأَنَا مَعَهُ وَخَرَجْتُ بِفَرَسِ ‏ ‏طَلْحَةَ ‏ ‏أُنَدِّيهِ عَلَى ‏ ‏ظَهْرِهِ ‏ ‏فَلَمَّا أَصْبَحْنَا إِذَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عُيَيْنَةَ الْفَزَارِيُّ ‏ ‏قَدْ ‏ ‏أَغَارَ ‏ ‏عَلَى ‏ ‏ظَهْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَاقَهُ ‏ ‏أَجْمَعَ ‏ ‏وَقَتَلَ رَاعِيَهُ ‏","","",""],[15922,15922,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْزِلًا فَجَاءَ عَيْنٌ لِلْمُشْرِكِينَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ يَتَصَبَّحُونَ فَدَعَوْهُ إِلَى طَعَامِهِمْ فَلَمَّا فَرَغَ الرَّجُلُ رَكِبَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَذَهَبَ مُسْرِعًا لِيُنْذِرَ أَصْحَابَهُ قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَأَدْرَكْتُهُ ‏ ‏فَأَنَخْتُ ‏ ‏رَاحِلَتَهُ ‏ ‏وَضَرَبْتُ عُنُقَهُ ‏ ‏فَغَنَّمَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَبَهُ ‏","","",""],[15923,15923,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَّافُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏قُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكُونُ أَحْيَانًا فِي الصَّيْدِ ‏ ‏فَأُصَلِّي فِي قَمِيصِي فَقَالَ ‏ ‏زُرَّهُ ‏ ‏وَلَوْ لَمْ تَجِدْ إِلَّا شَوْكَةً ‏","","",""],[15924,15924,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ وَالْعَشَاءُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[15925,15925,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَّافٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ إِبْرَاهِيمَ بْنِ أَبِي رَبِيعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَلَمَةَ بْنَ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أَكُونُ فِي الصَّيْدِ ‏ ‏فَأُصَلِّي وَلَيْسَ عَلَيَّ إِلَّا قَمِيصٌ وَاحِدٌ قَالَ ‏ ‏فَزُرَّهُ ‏ ‏وَإِنْ لَمْ تَجِدْ إِلَّا شَوْكَةً ‏","","",""],[15926,15926,"","","‏ ‏قَالَ ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَوَازِنَ ‏ ‏قَالَ فَبَيْنَمَا نَحْنُ ‏ ‏نَتَضَحَّى ‏ ‏وَعَامَّتُنَا مُشَاةٌ فِينَا ضَعَفَةٌ إِذْ جَاءَ رَجُلٌ عَلَى جَمَلٍ أَحْمَرَ فَانْتَزَعَ ‏ ‏طَلَقًا ‏ ‏عَنْ ‏ ‏حَقَبِهِ ‏ ‏فَقَيَّدَ بِهِ جَمَلَهُ رَجُلٌ شَابٌّ ثُمَّ جَاءَ يَتَغَدَّى مَعَ الْقَوْمِ فَلَمَّا رَأَى ضَعْفَهُمْ وَرِقَّةَ ‏ ‏ظَهْرِهِمْ ‏ ‏خَرَجَ إِلَى جَمَلِهِ فَأَطْلَقَهُ ثُمَّ ‏ ‏أَنَاخَهُ ‏ ‏فَقَعَدَ عَلَيْهِ فَخَرَجَ ‏ ‏يَرْكُضُ ‏ ‏وَتَبِعَهُ رَجُلٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏مِنْ ‏ ‏صَحَابَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى نَاقَةٍ ‏ ‏وَرْقَاءَ ‏ ‏هِيَ أَمْثَلُ ‏ ‏ظَهْرِ ‏ ‏الْقَوْمِ فَأَتْبَعَهُ قَالَ وَخَرَجْتُ ‏ ‏أَعْدُو فَأَدْرَكْتُهُ وَرَأْسُ النَّاقَةِ عِنْدَ وَرِكِ الْجَمَلِ وَكُنْتُ عِنْدَ وَرِكِ النَّاقَةِ ثُمَّ تَقَدَّمْتُ حَتَّى كُنْتُ عِنْدَ وَرِكِ الْجَمَلِ ثُمَّ تَقَدَّمْتُ حَتَّى أَخَذْتُ ‏ ‏بِخِطَامِ ‏ ‏الْجَمَلِ ‏ ‏فَأَنَخْتُهُ ‏ ‏فَلَمَّا وَضَعَ رُكْبَتَهُ إِلَى الْأَرْضِ ‏ ‏اخْتَرَطْتُ ‏ ‏سَيْفِي فَأَضْرِبُ بِهِ رَأْسَهُ ‏ ‏فَنَدَرَ ‏ ‏فَجِئْتُ ‏ ‏بِرَاحِلَتِهِ ‏ ‏وَمَا عَلَيْهَا أَقُودُهُ فَاسْتَقْبَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُقْبِلًا قَالَ مَنْ قَتَلَ الرَّجُلَ قَالُوا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏لَهُ ‏ ‏سَلَبُهُ ‏ ‏أَجْمَعُ ‏","","",""],[15927,15927,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولُ أَحَدٌ عَلَيَّ بَاطِلًا ‏ ‏أَوْ مَا لَمْ أَقُلْ ‏ ‏إِلَّا ‏ ‏تَبَوَّأَ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[15928,15928,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏خَرَجْنَا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏خَيْبَرَ ‏ ‏فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَيْ ‏ ‏عَامِرُ ‏ ‏لَوْ أَسْمَعْتَنَا مِنْ ‏ ‏هُنَيَّاتِكَ ‏ ‏قَالَ فَنَزَلَ ‏ ‏يَحْدُو ‏ ‏بِهِمْ وَيَذْكُرُ ‏ ‏تَالَلَّهِ لَوْلَا اللَّهُ مَا اهْتَدَيْنَا ‏ ‏وَذَكَرَ شِعْرًا غَيْرَ هَذَا وَلَكِنْ لَمْ أَحْفَظْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَذَا السَّائِقُ قَالُوا ‏ ‏عَامِرُ بْنُ الْأَكْوَعِ ‏ ‏فَقَالَ يَرْحَمُهُ اللَّهُ فَقَالَ رَجُلٌ مِنْ الْقَوْمِ يَا نَبِيَّ اللَّهِ لَوْلَا ‏ ‏مَتَّعْتَنَا ‏ ‏بِهِ فَلَمَّا ‏ ‏اصَّافَّ ‏ ‏الْقَوْمُ قَاتَلُوهُمْ فَأُصِيبَ ‏ ‏عَامِرُ بْنُ الْأَكْوَعِ ‏ ‏بِقَائِمِ سَيْفِ نَفْسِهِ فَمَاتَ فَلَمَّا أَمْسَوْا أَوْقَدُوا نَارًا كَثِيرَةً فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا هَذِهِ النَّارُ عَلَى أَيِّ شَيْءٍ تُوقَدُ قَالُوا عَلَى حُمُرٍ إِنْسِيَّةٍ قَالَ ‏ ‏أَهْرِيقُوا ‏ ‏مَا فِيهَا وَكَسِّرُوهَا فَقَالَ رَجُلٌ أَلَا ‏ ‏نُهَرِيقُ ‏ ‏مَا فِيهَا وَنَغْسِلُهَا قَالَ أَوْ ذَاكَ ‏","","",""],[15929,15929,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏أَذِّنْ فِي قَوْمِكَ ‏ ‏أَوْ فِي النَّاسِ ‏ ‏يَوْمَ عَاشُورَاءَ ‏ ‏مَنْ أَكَلَ فَلْيَصُمْ بَقِيَّةَ يَوْمِهِ وَمَنْ لَمْ يَكُنْ أَكَلَ فَلْيَصُمْ ‏","","",""],[15930,15930,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُتِيَ بِجِنَازَةٍ فَقَالُوا يَا نَبِيَّ اللَّهِ صَلِّ عَلَيْهَا قَالَ ‏ ‏هَلْ تَرَكَ شَيْئًا قَالُوا لَا قَالَ هَلْ تَرَكَ عَلَيْهِ دَيْنًا قَالُوا لَا فَصَلَّى عَلَيْهِ ثُمَّ أُتِيَ بِجَنَازَةٍ بَعْدَ ذَلِكَ فَقَالَ هَلْ تَرَكَ عَلَيْهِ مِنْ دَيْنٍ قَالُوا لَا قَالَ هَلْ تَرَكَ مِنْ شَيْءٍ قَالُوا ثَلَاثَ دَنَانِيرَ قَالَ ثَلَاثُ كَيَّاتٍ قَالَ فَأُتِيَ بِالثَّالِثَةِ فَقَالَ هَلْ تَرَكَ عَلَيْهِ مِنْ دَيْنٍ قَالُوا نَعَمْ قَالَ هَلْ تَرَكَ مِنْ شَيْءٍ قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏أَبُو قَتَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ عَلَيَّ دَيْنُهُ فَصَلَّى عَلَيْهِ ‏","","",""],[15931,15931,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى قَوْمٍ مِنْ ‏ ‏أَسْلَمَ ‏ ‏وَهُمْ ‏ ‏يَتَنَاضَلُونَ ‏ ‏فِي السُّوقِ فَقَالَ ‏ ‏ارْمُوا يَا ‏ ‏بَنِي إِسْمَاعِيلَ ‏ ‏فَإِنَّ أَبَاكُمْ كَانَ رَامِيًا ارْمُوا وَأَنَا مَعَ بَنِي فُلَانٍ لِأَحَدِ الْفَرِيقَيْنِ فَأَمْسَكُوا أَيْدِيَهُمْ فَقَالَ ارْمُوا قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ ‏ ‏نَرْمِي وَأَنْتَ مَعَ بَنِي فُلَانٍ قَالَ ارْمُوا وَأَنَا مَعَكُمْ كُلُّكُمْ ‏","","",""],[15932,15932,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ بْنِ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَجُلًا عَطَسَ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْحَمُكَ اللَّهُ ثُمَّ عَطَسَ الثَّانِيَةَ ‏ ‏أَوْ الثَّالِثَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ مَزْكُومٌ ‏","","",""],[15933,15933,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏رَجُلًا ‏ ‏يَأْكُلُ بِشِمَالِهِ فَقَالَ ‏ ‏كُلْ بِيَمِينِكَ قَالَ لَا أَسْتَطِيعُ قَالَ لَا اسْتَطَعْتَ قَالَ فَمَا وَصَلَتْ إِلَى ‏ ‏فِيهِ بَعْدُ ‏","","",""],[15934,15934,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عَيْنٌ ‏ ‏لِلْمُشْرِكِينَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَلَمَّا طَعِمَ ‏ ‏انْسَلَّ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الرَّجُلِ اقْتُلُوا قَالَ فَابْتَدَرَ الْقَوْمُ قَالَ وَكَانَ أَبِي ‏ ‏يَسْبِقُ ‏ ‏الْفَرَسَ شَدًّا قَالَ فَسَبَقَهُمْ إِلَيْهِ قَالَ فَأَخَذَ ‏ ‏بِزِمَامِ ‏ ‏نَاقَتِهِ ‏ ‏أَوْ ‏ ‏بِخِطَامِهَا ‏ ‏قَالَ ثُمَّ قَتَلَهُ قَالَ ‏ ‏فَنَفَّلَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَبَهُ ‏","","",""],[15935,15935,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الْمَغْرِبَ سَاعَةَ تَغْرُبُ الشَّمْسُ إِذَا غَابَ حَاجِبُهَا ‏","","",""],[15936,15936,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَلَى أَيِّ شَيْءٍ ‏ ‏بَايَعْتُمْ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏قَالَ ‏ ‏بَايَعْنَاهُ ‏ ‏عَلَى الْمَوْتِ ‏","","",""],[15937,15937,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ بْنَ مُحَمَّدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَسَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَا ‏ ‏خَرَجَ عَلَيْنَا مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَى إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ ‏ ‏أَذِنَ ‏ ‏لَكُمْ ‏ ‏فَاسْتَمْتِعُوا ‏ ‏يَعْنِي ‏ ‏مُتْعَةَ النِّسَاءِ ‏","","",""],[15938,15938,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏وَحَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كُنْتُ أُسَافِرُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا رَأَيْتُهُ صَلَّى بَعْدَ الْعَصْرِ وَلَا بَعْدَ الصُّبْحِ قَطُّ ‏","","",""],[15939,15939,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَوَازِنَ ‏ ‏وَغَطَفَانَ ‏ ‏فَبَيْنَمَا نَحْنُ كَذَلِكَ إِذْ جَاءَ رَجُلٌ عَلَى جَمَلٍ أَحْمَرَ فَانْتَزَعَ شَيْئًا مِنْ ‏ ‏حَقَبِ ‏ ‏الْبَعِيرِ فَقَيَّدَ بِهِ الْبَعِيرَ ثُمَّ جَاءَ يَمْشِي حَتَّى قَعَدَ مَعَنَا يَتَغَدَّى قَالَ فَنَظَرَ فِي الْقَوْمِ فَإِذَا ‏ ‏ظَهْرُهُمْ ‏ ‏فِيهِ قِلَّةٌ وَأَكْثَرُهُمْ مُشَاةٌ فَلَمَّا نَظَرَ إِلَى الْقَوْمِ خَرَجَ يَعْدُو قَالَ فَأَتَى بَعِيرَهُ فَقَعَدَ عَلَيْهِ قَالَ فَخَرَجَ ‏ ‏يَرْكُضُهُ ‏ ‏وَهُوَ ‏ ‏طَلِيعَةٌ ‏ ‏لِلْكُفَّارِ فَاتَّبَعَهُ رَجُلٌ مِنَّا مِنْ ‏ ‏أَسْلَمَ ‏ ‏عَلَى نَاقَةٍ لَهُ ‏ ‏وَرْقَاءَ ‏ ‏قَالَ ‏ ‏إِيَاسٌ ‏ ‏قَالَ أَبِي فَاتَّبَعْتُهُ ‏ ‏أَعْدُو عَلَى رِجْلَيَّ قَالَ وَرَأْسُ النَّاقَةِ عِنْدَ وَرِكِ الْجَمَلِ قَالَ وَلَحِقْتُهُ فَكُنْتُ عِنْدَ وَرِكِ النَّاقَةِ وَتَقَدَّمْتُ حَتَّى كُنْتُ عِنْدَ وَرِكِ الْجَمَلِ ثُمَّ تَقَدَّمْتُ حَتَّى أَخَذْتُ ‏ ‏بِخِطَامِ ‏ ‏الْجَمَلِ فَقُلْتُ لَهُ إِخْ فَلَمَّا وَضْعَ الْجَمَلُ رُكْبَتَهُ إِلَى الْأَرْضِ ‏ ‏اخْتَرَطْتُ ‏ ‏سَيْفِي فَضَرَبْتُ رَأْسَهُ ‏ ‏فَنَدَرَ ‏ ‏ثُمَّ جِئْتُ بِرَاحِلَتِهِ أَقُودُهَا فَاسْتَقْبَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ النَّاسِ قَالَ مَنْ قَتَلَ هَذَا الرَّجُلَ قَالُوا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهُ ‏ ‏سَلَبُهُ ‏ ‏أَجْمَعُ ‏","","",""],[15940,15940,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى ‏ ‏فَزَارَةَ ‏ ‏وَخَرَجْتُ مَعَهُ حَتَّى إِذَا ‏ ‏دَنَوْنَا ‏ ‏مِنْ الْمَاءِ ‏ ‏عَرَّسَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَتَّى إِذَا صَلَّيْنَا الصُّبْحَ أَمَرَنَا ‏ ‏فَشَنَنَّا ‏ ‏الْغَارَةَ ‏ ‏فَوَرَدْنَا ‏ ‏الْمَاءَ فَقَتَلَ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَنْ قَتَلَ وَنَحْنُ مَعَهُ قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَرَأَيْتُ ‏ ‏عُنُقًا ‏ ‏مِنْ النَّاسِ فِيهِمْ ‏ ‏الذَّرَارِيُّ ‏ ‏فَخَشِيتُ أَنْ يَسْبِقُونِي إِلَى الْجَبَلِ فَأَدْرَكْتُهُمْ فَرَمَيْتُ بِسَهْمٍ بَيْنَهُمْ وَبَيْنَ الْجَبَلِ فَلَمَّا رَأَوْا السَّهْمَ قَامُوا فَإِذَا امْرَأَةٌ مِنْ ‏ ‏فَزَارَةَ ‏ ‏عَلَيْهَا ‏ ‏قَشْعٌ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏مَعَهَا ابْنَةٌ مِنْ أَحْسَنِ ‏ ‏الْعَرَبِ ‏ ‏فَجِئْتُ أَسُوقُهُنَّ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَنَفَّلَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏ابْنَتَهَا فَلَمْ أَكْشِفْ لَهَا ثَوْبًا حَتَّى قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏ثُمَّ بَاتَتْ عِنْدِي فَلَمْ أَكْشِفْ لَهَا ثَوْبًا حَتَّى لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السُّوقِ فَقَالَ يَا ‏ ‏سَلَمَةُ ‏ ‏هَبْ لِي الْمَرْأَةَ قَالَ يَا رَسُولَ اللَّهِ لَقَدْ أَعْجَبَتْنِي وَمَا كَشَفْتُ لَهَا ثَوْبًا قَالَ فَسَكَتَ حَتَّى إِذَا كَانَ الْغَدُ لَقِيَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي السُّوقِ وَلَمْ أَكْشِفْ لَهَا ثَوْبًا فَقَالَ يَا ‏ ‏سَلَمَةُ ‏ ‏هَبْ لِي الْمَرْأَةَ لِلَّهِ أَبُوكَ قَالَ قُلْتُ هِيَ لَكَ يَا رَسُولَ اللَّهِ قَالَ فَبَعَثَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏فَفَدَى بِهَا أُسَرَاءَ مِنْ الْمُسْلِمِينَ كَانُوا فِي أَيْدِي الْمُشْرِكِينَ ‏","","",""],[15941,15941,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏بَارَزَ عَمِّي يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏مَرْحَبٌ ‏ ‏الْيَهُودِيُّ فَقَالَ ‏ ‏مَرْحَبٌ ‏ ‏قَدْ عَلِمَتْ ‏ ‏خَيْبَرُ ‏ ‏أَنِّي ‏ ‏مَرْحَبُ ‏ ‏شَاكِي السِّلَاحِ بَطَلٌ مُجَرَّبُ ‏ ‏إِذَا الْحُرُوبُ أَقْبَلَتْ ‏ ‏تَلَهَّبُ ‏ ‏فَقَالَ عَمِّي ‏ ‏عَامِرٌ ‏ ‏قَدْ عَلِمَتْ ‏ ‏خَيْبَرُ ‏ ‏أَنِّي ‏ ‏عَامِرُ ‏ ‏شَاكِي السِّلَاحِ بَطَلٌ ‏ ‏مُغَامِرُ ‏ ‏فَاخْتَلَفَا ضَرْبَتَيْنِ فَوَقَعَ سَيْفُ ‏ ‏مَرْحَبٍ ‏ ‏فِي ‏ ‏تُرْسِ ‏ ‏عَامِرٍ ‏ ‏وَذَهَبَ ‏ ‏يَسْفُلُ ‏ ‏لَهُ فَرَجَعَ السَّيْفُ عَلَى سَاقِهِ قَطَعَ ‏ ‏أَكْحَلَهُ ‏ ‏فَكَانَتْ فِيهَا نَفْسُهُ قَالَ ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ ‏ ‏لَقِيتُ نَاسًا مِنْ ‏ ‏صَحَابَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا بَطَلَ عَمَلُ ‏ ‏عَامِرٍ ‏ ‏قَتَلَ نَفْسَهُ قَالَ ‏ ‏سَلَمَةُ ‏ ‏فَجِئْتُ إِلَى نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْكِي قُلْتُ يَا رَسُولَ اللَّهِ بَطَلَ عَمَلُ ‏ ‏عَامِرٍ ‏ ‏قَالَ مَنْ قَالَ ذَاكَ قُلْتُ نَاسٌ مِنْ أَصْحَابِكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبَ مَنْ قَالَ ذَاكَ بَلْ ‏ ‏لَهُ أَجْرُهُ مَرَّتَيْنِ إِنَّهُ حِينَ خَرَجَ إِلَى ‏ ‏خَيْبَرَ ‏ ‏جَعَلَ ‏ ‏يَرْجُزُ ‏ ‏بِأَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِيهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسُوقُ ‏ ‏الرِّكَابَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏تَالَلَّهِ لَوْلَا اللَّهُ مَا اهْتَدَيْنَا ‏ ‏وَلَا تَصَدَّقْنَا وَلَا صَلَّيْنَا ‏ ‏إِنَّ الَّذِينَ قَدْ ‏ ‏بَغَوْا ‏ ‏عَلَيْنَا ‏ ‏إِذَا أَرَادُوا ‏ ‏فِتْنَةً ‏ ‏أَبَيْنَا ‏ ‏وَنَحْنُ عَنْ فَضْلِكَ مَا اسْتَغْنَيْنَا ‏ ‏فَثَبِّتْ الْأَقْدَامَ إِنْ لَاقَيْنَا ‏ ‏وَأَنْزِلَنْ ‏ ‏سَكِينَةً ‏ ‏عَلَيْنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَذَا قَالَ ‏ ‏عَامِرٌ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ غَفَرَ لَكَ رَبُّكَ قَالَ وَمَا اسْتَغْفَرَ لِإِنْسَانٍ قَطُّ يَخُصُّهُ إِلَّا اسْتُشْهِدَ فَلَمَّا سَمِعَ ذَلِكَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ لَوْ ‏ ‏مَتَّعْتَنَا ‏ ‏بِعَامِرٍ فَقَدِمَ فَاسْتُشْهِدَ قَالَ ‏ ‏سَلَمَةُ ‏ ‏ثُمَّ إِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسَلَنِي إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَقَالَ لَأُعْطِيَنَّ ‏ ‏الرَّايَةَ ‏ ‏الْيَوْمَ رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ ‏ ‏أَوْ يُحِبُّهُ اللَّهُ وَرَسُولُهُ ‏ ‏قَالَ فَجِئْتُ بِهِ أَقُودُهُ ‏ ‏أَرْمَدَ ‏ ‏فَبَصَقَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عَيْنِهِ ثُمَّ أَعْطَاهُ ‏ ‏الرَّايَةَ ‏ ‏فَخَرَجَ ‏ ‏مَرْحَبٌ ‏ ‏يَخْطِرُ ‏ ‏بِسَيْفِهِ فَقَالَ ‏ ‏قَدْ عَلِمَتْ ‏ ‏خَيْبَرُ ‏ ‏أَنِّي ‏ ‏مَرْحَبُ ‏ ‏شَاكِي السِّلَاحِ بَطَلٌ مُجَرَّبُ ‏ ‏إِذَا الْحُرُوبُ أَقْبَلَتْ ‏ ‏تَلَهَّبُ ‏ ‏فَقَالَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏كَرَّمَ اللَّهُ وَجْهَهُ ‏ ‏أَنَا الَّذِي سَمَّتْنِي أُمِّي ‏ ‏حَيْدَرَهْ ‏ ‏كَلَيْثِ ‏ ‏غَابَاتٍ كَرِيهِ ‏ ‏الْمَنْظَرَهْ ‏ ‏أُوفِيهِمُ ‏ ‏بِالصَّاعِ ‏ ‏كَيْلَ ‏ ‏السَّنْدَرَهْ ‏ ‏فَفَلَقَ رَأْسَ ‏ ‏مَرْحَبٍ ‏ ‏بِالسَّيْفِ وَكَانَ الْفَتْحُ عَلَى يَدَيْهِ ‏","","",""],[15942,15942,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْنَا أَنَا ‏ ‏وَرَبَاحٌ ‏ ‏غُلَامُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِظَهْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجْتُ بِفَرَسٍ ‏ ‏لِطَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏كُنْتُ أُرِيدُ أَنْ ‏ ‏أُبْدِيَهُ ‏ ‏مَعَ الْإِبِلِ فَلَمَّا كَانَ ‏ ‏بِغَلَسٍ ‏ ‏غَارَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عُيَيْنَةَ ‏ ‏عَلَى إِبِلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَتَلَ رَاعِيَهَا وَخَرَجَ يَطْرُدُهَا هُوَ وَأُنَاسٌ مَعَهُ فِي خَيْلٍ فَقُلْتُ يَا ‏ ‏رَبَاحُ ‏ ‏اقْعُدْ عَلَى هَذَا الْفَرَسِ فَأَلْحِقْهُ ‏ ‏بِطَلْحَةَ ‏ ‏وَأَخْبِرْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَدْ أُغِيرَ عَلَى ‏ ‏سَرْحِهِ ‏ ‏قَالَ وَقُمْتُ عَلَى تَلٍّ فَجَعَلْتُ وَجْهِي مِنْ قِبَلِ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ نَادَيْتُ ثَلَاثَ مَرَّاتٍ ‏ ‏يَا ‏ ‏صَبَاحَاهْ ‏ ‏ثُمَّ اتَّبَعْتُ الْقَوْمَ مَعِي سَيْفِي وَنَبْلِي فَجَعَلْتُ أَرْمِيهِمْ ‏ ‏وَأَعْقِرُ ‏ ‏بِهِمْ وَذَلِكَ حِينَ يَكْثُرُ الشَّجَرُ فَإِذَا رَجَعَ إِلَيَّ فَارِسٌ جَلَسْتُ لَهُ فِي أَصْلِ شَجَرَةٍ ثُمَّ رَمَيْتُ فَلَا يُقْبِلُ عَلَيَّ فَارِسٌ إِلَّا ‏ ‏عَقَرْتُ ‏ ‏بِهِ فَجَعَلْتُ أَرْمِيهِمْ وَأَنَا أَقُولُ ‏ ‏أَنَا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏وَالْيَوْمُ يَوْمُ الرُّضَّعِ ‏ ‏فَأَلْحَقُ بِرَجُلٍ مِنْهُمْ ‏ ‏فَأَرْمِيهِ وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏فَيَقَعُ سَهْمِي فِي الرَّحْلِ حَتَّى انْتَظَمْتُ كَتِفَهُ فَقُلْتُ خُذْهَا ‏ ‏وَأَنَا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏وَالْيَوْمُ يَوْمُ الرُّضَّعِ ‏ ‏فَإِذَا كُنْتُ فِي الشَّجَرِ أَحْرَقْتُهُمْ بِالنَّبْلِ فَإِذَا تَضَايَقَتْ ‏ ‏الثَّنَايَا ‏ ‏عَلَوْتُ الْجَبَلَ ‏ ‏فَرَدَيْتُهُمْ ‏ ‏بِالْحِجَارَةِ فَمَا زَالَ ذَاكَ شَأْنِي وَشَأْنَهُمْ أَتْبَعُهُمْ ‏ ‏فَأَرْتَجِزُ ‏ ‏حَتَّى مَا خَلَقَ اللَّهُ شَيْئًا مِنْ ‏ ‏ظَهْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا خَلَّفْتُهُ ‏ ‏وَرَاءَ ظَهْرِي فَاسْتَنْقَذْتُهُ مِنْ أَيْدِيهِمْ ثُمَّ لَمْ أَزَلْ أَرْمِيهِمْ حَتَّى أَلْقَوْا أَكْثَرَ مِنْ ثَلَاثِينَ رُمْحًا وَأَكْثَرَ مِنْ ثَلَاثِينَ ‏ ‏بُرْدَةً ‏ ‏يَسْتَخِفُّونَ مِنْهَا وَلَا يُلْقُونَ مِنْ ذَلِكَ شَيْئًا إِلَّا جَعَلْتُ عَلَيْهِ حِجَارَةً وَجَمَعْتُ عَلَى طَرِيقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا امْتَدَّ الضُّحَى أَتَاهُمْ ‏ ‏عُيَيْنَةُ بْنُ بَدْرٍ الْفَزَارِيُّ ‏ ‏مَدَدًا ‏ ‏لَهُمْ وَهُمْ فِي ‏ ‏ثَنِيَّةٍ ‏ ‏ضَيِّقَةٍ ثُمَّ عَلَوْتُ الْجَبَلَ فَأَنَا فَوْقَهُمْ فَقَالَ ‏ ‏عُيَيْنَةُ ‏ ‏مَا هَذَا الَّذِي أَرَى قَالُوا لَقِينَا مِنْ هَذَا ‏ ‏الْبَرْحَ ‏ ‏مَا فَارَقَنَا ‏ ‏بِسَحَرٍ ‏ ‏حَتَّى الْآنَ وَأَخَذَ كُلَّ شَيْءٍ فِي أَيْدِينَا وَجَعَلَهُ وَرَاءَ ظَهْرِهِ قَالَ ‏ ‏عُيَيْنَةُ ‏ ‏لَوْلَا أَنَّ هَذَا يَرَى أَنَّ وَرَاءَهُ طَلَبًا لَقَدْ تَرَكَكُمْ لِيَقُمْ إِلَيْهِ ‏ ‏نَفَرٌ ‏ ‏مِنْكُمْ فَقَامَ إِلَيْهِ مِنْهُمْ أَرْبَعَةٌ فَصَعِدُوا فِي الْجَبَلِ فَلَمَّا أَسْمَعْتُهُمْ الصَّوْتَ قُلْتُ أَتَعْرِفُونِي قَالُوا وَمَنْ أَنْتَ قُلْتُ أَنَا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏وَالَّذِي كَرَّمَ وَجْهَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَطْلُبُنِي مِنْكُمْ رَجُلٌ فَيُدْرِكُنِي وَلَا أَطْلُبُهُ ‏ ‏فَيَفُوتُنِي ‏ ‏قَالَ رَجُلٌ مِنْهُمْ إِنْ أَظُنُّ قَالَ فَمَا ‏ ‏بَرِحْتُ ‏ ‏مَقْعَدِي ذَلِكَ حَتَّى نَظَرْتُ إِلَى فَوَارِسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُونَ الشَّجَرَ وَإِذَا أَوَّلُهُمْ ‏ ‏الْأَخْرَمُ الْأَسَدِيُّ ‏ ‏وَعَلَى ‏ ‏أَثَرِهِ ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَارِسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى أَثَرِ ‏ ‏أَبِي قَتَادَةَ ‏ ‏الْمِقْدَادُ الْكِنْدِيُّ ‏ ‏فَوَلَّى الْمُشْرِكُونَ ‏ ‏مُدْبِرِينَ ‏ ‏وَأَنْزِلُ مِنْ الْجَبَلِ فَأَعْرِضُ ‏ ‏لِلْأَخْرَمِ ‏ ‏فَآخُذُ ‏ ‏بِعِنَانِ ‏ ‏فَرَسِهِ فَقُلْتُ يَا ‏ ‏أَخْرَمُ ‏ ‏ائْذَنْ ‏ ‏الْقَوْمَ ‏ ‏يَعْنِي احْذَرْهُمْ ‏ ‏فَإِنِّي لَا آمَنُ أَنْ يَقْطَعُوكَ ‏ ‏فَاتَّئِدْ ‏ ‏حَتَّى يَلْحَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ قَالَ يَا ‏ ‏سَلَمَةُ ‏ ‏إِنْ كُنْتَ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَتَعْلَمُ أَنَّ الْجَنَّةَ حَقٌّ وَالنَّارَ حَقٌّ فَلَا تَحُلْ بَيْنِي وَبَيْنَ الشَّهَادَةِ قَالَ فَخَلَّيْتُ ‏ ‏عِنَانَ ‏ ‏فَرَسِهِ فَيَلْحَقُ ‏ ‏بِعَبْدِ الرَّحْمَنِ بْنِ عُيَيْنَةَ ‏ ‏وَيَعْطِفُ عَلَيْهِ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَاخْتَلَفَا ‏ ‏طَعْنَتَيْنِ ‏ ‏فَعَقَرَ ‏ ‏الْأَخْرَمُ ‏ ‏بِعَبْدِ الرَّحْمَنِ ‏ ‏وَطَعَنَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَقَتَلَهُ فَتَحَوَّلَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ فَرَسِ ‏ ‏الْأَخْرَمِ ‏ ‏فَيَلْحَقُ ‏ ‏أَبُو قَتَادَةَ ‏ ‏بِعَبْدِ الرَّحْمَنِ ‏ ‏فَاخْتَلَفَا طَعْنَتَيْنِ ‏ ‏فَعَقَرَ ‏ ‏بِأَبِي قَتَادَةَ ‏ ‏وَقَتَلَهُ ‏ ‏أَبُو قَتَادَةَ ‏ ‏وَتَحَوَّلَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏عَلَى فَرَسِ ‏ ‏الْأَخْرَمِ ‏ ‏ثُمَّ إِنِّي خَرَجْتُ ‏ ‏أَعْدُو ‏ ‏فِي ‏ ‏أَثَرِ ‏ ‏الْقَوْمِ حَتَّى مَا أَرَى مِنْ غُبَارِ ‏ ‏صَحَابَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا ‏ ‏وَيُعْرِضُونَ ‏ ‏قَبْلَ غَيْبُوبَةِ الشَّمْسِ إِلَى ‏ ‏شِعْبٍ ‏ ‏فِيهِ مَاءٌ يُقَالُ لَهُ ‏ ‏ذُو قَرَدٍ ‏ ‏فَأَرَادُوا أَنْ يَشْرَبُوا مِنْهُ فَأَبْصَرُونِي ‏ ‏أَعْدُو ‏ ‏وَرَاءَهُمْ ‏ ‏فَعَطَفُوا ‏ ‏عَنْهُ وَاشْتَدُّوا فِي ‏ ‏الثَّنِيَّةِ ‏ ‏ثَنِيَّةِ ذِي بِئْرٍ ‏ ‏وَغَرَبَتْ الشَّمْسُ فَأَلْحَقُ رَجُلًا ‏ ‏فَأَرْمِيهِ فَقُلْتُ خُذْهَا ‏ ‏وَأَنَا ‏ ‏ابْنُ الْأَكْوَعِ ‏ ‏وَالْيَوْمُ يَوْمُ الرُّضَّعِ ‏ ‏قَالَ فَقَالَ ‏ ‏يَا ثُكْلَ ‏ ‏أُمِّ أَكْوَعَ ‏ ‏بَكْرَةً ‏ ‏قُلْتُ نَعَمْ أَيْ عَدُوَّ نَفْسِهِ وَكَانَ الَّذِي رَمَيْتُهُ ‏ ‏بَكْرَةً ‏ ‏فَأَتْبَعْتُهُ سَهْمًا آخَرَ فَعَلِقَ بِهِ سَهْمَانِ وَيَخْلُفُونَ فَرَسَيْنِ فَجِئْتُ بِهِمَا أَسُوقُهُمَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمَاءِ الَّذِي ‏ ‏جَلَّيْتُهُمْ ‏ ‏عَنْهُ ‏ ‏ذُوْ قَرَدٍ ‏ ‏فَإِذَا بِنَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خَمْسِ مِائَةٍ وَإِذَا ‏ ‏بِلَالٌ ‏ ‏قَدْ ‏ ‏نَحَرَ ‏ ‏جَزُورًا ‏ ‏مِمَّا خَلَّفْتُ فَهُوَ ‏ ‏يَشْوِي لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ كَبِدِهَا ‏ ‏وَسَنَامِهَا ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ خَلِّنِي ‏ ‏فَأَنْتَخِبَ ‏ ‏مِنْ أَصْحَابِكَ مِائَةً فَآخُذَ عَلَى الْكُفَّارِ ‏ ‏عَشْوَةً ‏ ‏فَلَا يَبْقَى مِنْهُمْ ‏ ‏مُخْبِرٌ ‏ ‏إِلَّا قَتَلْتُهُ قَالَ أَكُنْتَ فَاعِلًا ذَلِكَ يَا ‏ ‏سَلَمَةُ ‏ ‏قَالَ نَعَمْ وَالَّذِي أَكْرَمَكَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْتُ ‏ ‏نَوَاجِذَهُ ‏ ‏فِي ضُوءِ النَّارِ ثُمَّ قَالَ إِنَّهُمْ ‏ ‏يُقْرَوْنَ ‏ ‏الْآنَ بِأَرْضِ ‏ ‏غَطَفَانَ ‏ ‏فَجَاءَ رَجُلٌ مِنْ ‏ ‏غَطَفَانَ ‏ ‏فَقَالَ مَرُّوا عَلَى فُلَانٍ ‏ ‏الْغَطَفَانِيِّ ‏ ‏فَنَحَرَ ‏ ‏لَهُمْ ‏ ‏جَزُورًا ‏ ‏قَالَ فَلَمَّا أَخَذُوا يَكْشِطُونَ جِلْدَهَا رَأَوْا غَبَرَةً فَتَرَكُوهَا وَخَرَجُوا هَرَبًا فَلَمَّا أَصْبَحْنَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ فُرْسَانِنَا الْيَوْمَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏وَخَيْرُ رَجَّالَتِنَا ‏ ‏سَلَمَةُ ‏ ‏فَأَعْطَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَهْمَ ‏ ‏الرَّاجِلِ ‏ ‏وَالْفَارِسِ جَمِيعًا ثُمَّ ‏ ‏أَرْدَفَنِي ‏ ‏وَرَاءَهُ عَلَى ‏ ‏الْعَضْبَاءِ ‏ ‏رَاجِعِينَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَلَمَّا كَانَ بَيْنَنَا وَبَيْنَهَا قَرِيبًا مِنْ ‏ ‏ضَحْوَةٍ ‏ ‏وَفِي الْقَوْمِ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏كَانَ لَا يُسْبَقُ جَعَلَ يُنَادِي هَلْ مِنْ مُسَابِقٍ أَلَا رَجُلٌ يُسَابِقُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَأَعَادَ ذَلِكَ مِرَارًا وَأَنَا وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْدِفِي ‏ ‏قُلْتُ لَهُ أَمَا تُكْرِمُ كَرِيمًا وَلَا تَهَابُ شَرِيفًا قَالَ لَا إِلَّا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قُلْتُ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي خَلِّنِي فَلَأُسَابِقُ الرَّجُلَ قَالَ إِنْ شِئْتَ قُلْتُ أَذْهَبُ إِلَيْكَ ‏ ‏فَطَفَرَ ‏ ‏عَنْ رَاحِلَتِهِ وَثَنَيْتُ رِجْلَيَّ ‏ ‏فَطَفَرْتُ ‏ ‏عَنْ النَّاقَةِ ثُمَّ إِنِّي رَبَطْتُ عَلَيْهَا ‏ ‏شَرَفًا ‏ ‏أَوْ ‏ ‏شَرَفَيْنِ ‏ ‏يَعْنِي اسْتَبْقَيْتُ نَفْسِي ‏ ‏ثُمَّ إِنِّي عَدَوْتُ حَتَّى أَلْحَقَهُ ‏ ‏فَأَصُكَّ ‏ ‏بَيْنَ كَتِفَيْهِ بِيَدَيَّ قُلْتُ سَبَقْتُكَ وَاللَّهِ ‏ ‏أَوْ كَلِمَةً نَحْوَهَا ‏ ‏قَالَ فَضَحِكَ وَقَالَ إِنْ أَظُنُّ حَتَّى قَدِمْنَا ‏ ‏الْمَدِينَةَ ‏","","",""],[15943,15943,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ أَبُو يَحْيَى ‏ ‏قَاضِي ‏ ‏الْيَمَامَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ وَالْعَشَاءُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[15944,15944,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏سَلَّ ‏ ‏عَلَيْنَا السَّيْفَ فَلَيْسَ مِنَّا ‏","","",""],[15945,15945,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏أَنَّهُ ‏ ‏كَانَ ‏ ‏يَتَحَرَّى ‏ ‏مَوْضِعَ الْمُصْحَفِ وَذَكَرَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَرَّى ‏ ‏ذَلِكَ الْمَكَانَ ‏ ‏وَكَانَ بَيْنَ الْمِنْبَرِ وَالْقِبْلَةِ مَمَرُّ شَاةٍ ‏","","",""],[15946,15946,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَبْعَ غَزَوَاتٍ فَذَكَرَ ‏ ‏الْحُدَيْبِيَةَ ‏ ‏وَيَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏وَيَوْمَ ‏ ‏الْقَرَدِ ‏ ‏وَيَوْمَ ‏ ‏خَيْبَرَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَنَسِيتُ بَقِيَّتَهُنَّ ‏","","",""],[15947,15947,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏قَالَ ‏ ‏جَاءَنِي عَمِّي ‏ ‏عَامِرٌ ‏ ‏فَقَالَ أَعْطِنِي سِلَاحَكَ قَالَ فَأَعْطَيْتُهُ قَالَ فَجِئْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَبْغِنِي سِلَاحَكَ قَالَ أَيْنَ سِلَاحُكَ قَالَ قُلْتُ أَعْطَيْتُهُ عَمِّي ‏ ‏عَامِرًا ‏ ‏قَالَ ‏ ‏مَا أَجِدُ شَبَهَكَ إِلَّا الَّذِي قَالَ هَبْ لِي أَخًا أَحَبَّ إِلَيَّ مِنْ نَفْسِي قَالَ فَأَعْطَانِي قَوْسَهُ ‏ ‏وَمَجَانَّهُ ‏ ‏وَثَلَاثَةَ أَسْهُمٍ مِنْ ‏ ‏كِنَانَتِهِ ‏","","",""],[15948,15948,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏أَنَّهُ اسْتَأْذَنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَدْوِ ‏ ‏فَأَذِنَ لَهُ ‏","","",""],[15949,15949,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ الْحَارِثِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏وَأَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِيَاسُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْجُمُعَةَ ثُمَّ نَرْجِعُ وَمَا ‏ ‏لِلْحِيطَانِ ‏ ‏فَيْءٌ ‏ ‏يُسْتَظَلُّ بِهِ ‏","","",""],[15950,15950,"","","‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَيُونُسُ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَّافُ بْنُ خَالِدٍ الْمَخْزُومِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏ابْنُ أَبِي رَبِيعَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَلَمَةَ بْنَ الْأَكْوَعِ ‏ ‏وَكَانَ إِذَا نَزَلَ يَنْزِلُ عَلَى أَبِي ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي أَكُونُ فِي الصَّيْدِ وَلَيْسَ عَلَيَّ إِلَّا قَمِيصٌ ‏ ‏أَفَأُصَلِّي فِيهِ قَالَ ‏ ‏زُرَّهُ ‏ ‏وَلَوْ لَمْ تَجِدْ إِلَّا شَوْكَةً ‏","","",""],[15951,15951,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَرُ بْنُ رَاشِدٍ الْيَمَامِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِيَاسُ بْنُ سَلَمَةَ بْنِ الْأَكْوَعِ الْأَسْلَمِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَفْتِحُ دُعَاءً إِلَّا اسْتَفْتَحَهُ بِسُبْحَانَ ‏ ‏رَبِّيَ الْأَعْلَى الْعَلِيِّ الْوَهَّابِ ‏","","",""],[15952,15952,"","","‏ ‏وَقَالَ ‏ ‏سَلَمَةُ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَنْ ‏ ‏بَايَعَهُ ‏ ‏تَحْتَ الشَّجَرَةِ ثُمَّ مَرَرْتُ بِهِ بَعْدَ ذَلِكَ وَمَعَهُ قَوْمٌ فَقَالَ ‏ ‏بَايِعْ ‏ ‏يَا ‏ ‏سَلَمَةُ ‏ ‏فَقُلْتُ قَدْ فَعَلْتُ قَالَ وَأَيْضًا ‏ ‏فَبَايَعْتُهُ ‏ ‏الثَّانِيَةَ ‏","","",""],[15953,15953,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏بَايَعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ عَدَلْتُ إِلَى ظِلِّ شَجَرَةٍ فَلَمَّا خَفَّ النَّاسُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا ‏ ‏ابْنَ الْأَكْوَعِ ‏ ‏أَلَا ‏ ‏تُبَايِعُ ‏ ‏قُلْتُ قَدْ ‏ ‏بَايَعْتُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ وَأَيْضًا قَالَ ‏ ‏فَبَايَعْتُهُ ‏ ‏الثَّانِيَةَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا مُسْلِمٍ ‏ ‏عَلَى أَيِّ شَيْءٍ ‏ ‏تُبَايِعُونَ ‏ ‏يَوْمَئِذٍ قَالَ ‏ ‏عَلَى الْمَوْتِ ‏","","",""],[15954,15954,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُصَلِّي الْمَغْرِبَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏تَوَارَتْ ‏ ‏بِالْحِجَابِ ‏","","",""],[15955,15955,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْعَطَّافُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ غَيْرُ ‏ ‏يُونُسَ بْنِ رَزِينٍ ‏ ‏أَنَّهُ ‏ ‏نَزَلَ ‏ ‏الرَّبَذَةَ ‏ ‏هُوَ وَأَصْحَابُهُ يُرِيدُونَ الْحَجَّ قِيلَ لَهُمْ هَاهُنَا ‏ ‏سَلَمَةُ بْنُ الْأَكْوَعِ صَاحِبُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْنَاهُ فَسَلَّمْنَا عَلَيْهِ ثُمَّ سَأَلْنَاهُ فَقَالَ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِي هَذِهِ وَأَخْرَجَ لَنَا كَفَّهُ كَفًّا ضَخْمَةً قَالَ فَقُمْنَا إِلَيْهِ فَقَبَّلْنَا ‏ ‏كَفَّيْهِ جَمِيعًا ‏","","",""],[15956,15956,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏عَنْ ‏ ‏إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏مُتْعَةِ النِّسَاءِ ‏ ‏عَامَ ‏ ‏أَوْطَاسٍ ‏ ‏ثَلَاثَةَ أَيَّامٍ ثُمَّ نَهَى عَنْهَا ‏","","",""],[15957,15957,"","","‏ ‏قَالَ ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ إِيَاسِ بْنِ سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏سَلَمَةَ ‏ ‏قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏فَلَقِيَهُ ‏ ‏بُرَيْدَةُ بْنُ الْحَصِيبِ ‏ ‏فَقَالَ ارْتَدَدْتَ عَنْ هِجْرَتِكَ يَا ‏ ‏سَلَمَةُ ‏ ‏فَقَالَ مَعَاذَ اللَّهِ إِنِّي فِي إِذْنٍ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ابْدُوا يَا ‏ ‏أَسْلَمُ ‏ ‏فَتَنَسَّمُوا الرِّيَاحَ وَاسْكُنُوا ‏ ‏الشِّعَابَ ‏ ‏فَقَالُوا إِنَّا نَخَافُ يَا رَسُولَ اللَّهِ أَنْ يَضُرَّنَا ذَلِكَ فِي هِجْرَتِنَا قَالَ أَنْتُمْ مُهَاجِرُونَ حَيْثُ كُنْتُمْ ‏","","",""],[15958,15958,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏مَوْلَى ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏أَنْتُمْ أَهْلُ بَدْوِنَا وَنَحْنُ أَهْلُ حَضَرِكُمْ ‏","","",""],[15959,15959,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَنْ ‏ ‏عَجُوزٍ ‏ ‏مِنْ ‏ ‏بَنِي نُمَيْرٍ ‏ ‏أَنَّهَا ‏ ‏رَمَقَتْ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي ‏ ‏بِالْأَبْطَحِ ‏ ‏تُجَاهَ ‏ ‏الْبَيْتِ ‏ ‏قَبْلَ الْهِجْرَةِ قَالَ فَسَمِعَتْهُ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي ذَنْبِي خَطَئِي وَجَهْلِي ‏","","",""],[15960,15960,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ فَرُّوخَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُصْعَبُ بْنُ نُوحٍ الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏أَدْرَكْتُ ‏ ‏عَجُوزًا ‏ ‏لَنَا كَانَتْ فِيمَنْ بَايَعْنَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَتَيْنَاهُ يَوْمًا فَأَخَذَ عَلَيْنَا ‏ ‏أَنْ لَا تَنُحْنَ قَالَتْ الْعَجُوزُ يَا رَسُولَ اللَّهِ إِنَّ نَاسًا كَانُوا قَدْ أَسْعَدُونِي عَلَى مُصِيبَةٍ أَصَابَتْنِي وَإِنَّهُمْ أَصَابَتْهُمْ مُصِيبَةٌ وَأَنَا أُرِيدُ أَنْ أُسْعِدَهُمْ ثُمَّ إِنَّهَا أَتَتْهُ فَبَايَعَتْهُ وَقَالَتْ هُوَ الْمَعْرُوفُ الَّذِي قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ ‏}","","",""],[15961,15961,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ بْنِ خَلَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ ‏ ‏بِالْإِهْلَالِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَنِي أَنْ آمُرَ أَصْحَابِي أَنْ يَرْفَعُوا أَصْوَاتَهُمْ ‏ ‏بِالْإِهْلَالِ ‏","","",""],[15962,15962,"","","‏ ‏قَالَ ‏ ‏أَنَسُ بْنُ عِيَاضٍ اللَّيْثِيُّ أَبُو ضَمْرَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ خُصَيْفَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏ظُلْمًا أَخَافَهُ اللَّهُ وَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[15963,15963,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ زَرَعَ زَرْعًا فَأَكَلَ مِنْهُ الطَّيْرُ أَوْ ‏ ‏الْعَافِيَةُ ‏ ‏كَانَ لَهُ بِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[15964,15964,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏أَخَافَهُ اللَّهُ عَزَّ وَجَلَّ وَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ يَوْمَ الْقِيَامَةِ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[15965,15965,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ يَعْنِي ابْنَ الْهَادِ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ شَيْءٍ يُصِيبُ الْمُؤْمِنَ حَتَّى الشَّوْكَةِ تُصِيبُهُ إِلَّا كَتَبَ اللَّهُ لَهُ بِهَا حَسَنَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[15966,15966,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ سَوَادَةَ الْجُذَامِيِّ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ خَيْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَهْلَةَ السَّائِبِ بْنِ خَلَّادٍ ‏ ‏أَنَّ رَجُلًا أَمَّ قَوْمًا فَبَصَقَ فِي الْقِبْلَةِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ فَرَغَ لَا يُصَلِّ لَكُمْ فَأَرَادَ بَعْدَ ذَلِكَ أَنْ يُصَلِّيَ لَهُمْ فَمَنَعُوهُ وَأَخْبَرُوهُ بِقَوْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ ‏ ‏وَحَسِبْتُ أَنَّهُ قَالَ آذَيْتَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[15967,15967,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَخَافَ ‏ ‏الْمَدِينَةَ ‏ ‏أَخَافَهُ اللَّهُ عَزَّ وَجَلَّ وَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يَقْبَلُ اللَّهُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[15968,15968,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا دَعَا جَعَلَ بَاطِنَ كَفَّيْهِ إِلَى وَجْهِهِ ‏","","",""],[15969,15969,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حَبَّانَ بْنِ وَاسِعٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ الْأَنْصَارِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا سَأَلَ جَعَلَ بَاطِنَ كَفَّيْهِ إِلَيْهِ وَإِذَا اسْتَعَاذَ جَعَلَ ظَاهِرَهُمَا إِلَيْهِ ‏","","",""],[15970,15970,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّ ‏ ‏عَطَاءَ بْنَ يَسَارٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏السَّائِبَ بْنَ خَلَّادٍ ‏ ‏أَخَا ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَافَ أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏ظَالِمًا أَخَافَهُ اللَّهُ وَكَانَتْ عَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ لَا يُقْبَلُ مِنْهُ ‏ ‏عَدْلٌ ‏ ‏وَلَا ‏ ‏صَرْفٌ ‏","","",""],[15971,15971,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُنْ عَجَّاجًا ثَجَّاجًا ‏ ‏وَالْعَجُّ التَّلْبِيَةُ وَالثَّجُّ نَحْرُ ‏ ‏الْبُدْنِ ‏","","",""],[15972,15972,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وحَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ أَنْ آمُرَ أَصْحَابِي ‏ ‏أَوْ مَنْ مَعِي ‏ ‏أَنْ ‏ ‏يَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ ‏ ‏أَوْ ‏ ‏بِالْإِهْلَالِ ‏ ‏يُرِيدُ أَحَدَهُمَا ‏","","",""],[15973,15973,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏خَلَّادُ بْنُ السَّائِبِ بْنِ سُوَيْدٍ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏السَّائِبِ بْنِ خَلَّادٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ يَأْمُرُكَ أَنْ تَأْمُرَ أَصْحَابَكَ أَنْ يَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ ‏ ‏وَالْإِهْلَالِ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏بِالتَّلْبِيَةِ ‏ ‏أَوْ ‏ ‏بِالْإِهْلَالِ ‏ ‏قَالَ وَلَا أَدْرِي أَيُّنَا ‏ ‏وَهِلَ ‏ ‏أَنَا ‏ ‏وَعَبْدُ اللَّهِ ‏ ‏أَوْ ‏ ‏خَلَّادٌ ‏ ‏فِي ‏ ‏الْإِهْلَالِ ‏ ‏أَوْ التَّلْبِيَةِ ‏","","",""],[15974,15974,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ بْنِ خَلَّادٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَقَالَ ‏ ‏مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ ‏ ‏بِالْإِهْلَالِ ‏","","",""],[15975,15975,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ أَبِي أَنَسٍ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ بْنِ عَلِيٍّ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏خُفَافِ بْنِ إِيمَاءِ بْنِ رَحَضَةَ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ وَنَحْنُ مَعَهُ فَلَمَّا رَفَعَ رَأْسَهُ مِنْ الرَّكْعَةِ الْآخِرَةِ قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏لِحْيَانًا ‏ ‏وَرِعْلًا ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ثُمَّ وَقَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاجِدًا فَلَمَّا انْصَرَفَ قَرَأَ عَلَى النَّاسِ فَقَالَ يَا أَيُّهَا النَّاسُ إِنِّي أَنَا لَسْتُ قُلْتُهُ وَلَكِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَهُ ‏","","",""],[15976,15976,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ حَرْمَلَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ خُفَافٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏خُفَافِ بْنِ إِيمَاءِ بْنِ رَحَضَةَ الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏رَكَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّلَاةِ ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَعُصَيَّةُ ‏ ‏عَصَتْ اللَّهَ وَرَسُولَهُ اللَّهُمَّ الْعَنْ ‏ ‏بَنِي لَحْيَانَ ‏ ‏اللَّهُمَّ الْعَنْ ‏ ‏رِعْلًا ‏ ‏وَذَكْوَانَ ‏ ‏ثُمَّ كَبَّرَ وَوَقَعَ سَاجِدًا ‏ ‏قَالَ ‏ ‏خُفَافٌ ‏ ‏فَجُعِلَتْ لَعْنَةُ الْكَفَرَةِ مِنْ أَجْلِ ذَلِكَ ‏","","",""],[15977,15977,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثْنِي ‏ ‏عَنْ افْتِرَاشِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخِذَهُ الْيُسْرَى فِي وَسَطِ الصَّلَاةِ وَفِي آخِرِهَا وَقُعُودِهِ عَلَى وَرِكِهِ الْيُسْرَى وَوَضْعِهِ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى وَنَصْبِهِ قَدَمَهُ الْيُمْنَى وَوَضْعِهِ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى وَنَصْبِهِ أُصْبُعَهُ السَّبَّابَةَ يُوَحِّدُ بِهَا رَبَّهُ عَزَّ وَجَلَّ ‏ ‏عِمْرَانُ بْنُ أَبِي أَنَسٍ ‏ ‏أَخُو ‏ ‏بَنِي عَامِرِ بْنِ لُؤَيٍّ ‏ ‏وَكَانَ ثِقَةً ‏ ‏عَنْ ‏ ‏أَبِي الْقَاسِمِ مِقْسَمٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ فِي مَسْجِدِ ‏ ‏بَنِي غِفَارٍ ‏ ‏فَلَمَّا ‏ ‏جَلَسْتُ فِي صَلَاتِي افْتَرَشْتُ فَخِذِي الْيُسْرَى وَنَصَبْتُ السَّبَّابَةَ قَالَ فَرَآنِي ‏ ‏خُفَافُ بْنُ إِيمَاءِ بْنِ رَحَضَةَ الْغِفَارِيُّ ‏ ‏وَكَانَ لَهُ صُحْبَةٌ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا أَصْنَعُ ذَلِكَ قَالَ فَلَمَّا انْصَرَفْتُ مِنْ صَلَاتِي قَالَ لِي أَيْ بُنَيَّ لِمَ نَصَبْتَ إِصْبَعَكَ هَكَذَا قَالَ وَمَا تُنْكِرُ رَأَيْتُ النَّاسَ يَصْنَعُونَ ذَلِكَ قَالَ فَإِنَّكَ أَصَبْتَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا صَلَّى يَصْنَعُ ذَلِكَ فَكَانَ الْمُشْرِكُونَ يَقُولُونَ إِنَّمَا يَصْنَعُ هَذَا ‏ ‏مُحَمَّدٌ ‏ ‏بِإِصْبَعِهِ يَسْحَرُهَا وَكَذَبُوا إِنَّمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ ذَلِكَ يُوَحِّدُ بِهَا رَبَّهُ عَزَّ وَجَلَّ ‏","","",""],[15978,15978,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ الْوَلِيدِ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي أَجِدُ وَحْشَةً قَالَ ‏ ‏إِذَا أَخَذْتَ مَضْجَعَكَ فَقُلْ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ غَضَبِهِ وَعِقَابِهِ وَشَرِّ عِبَادِهِ وَمِنْ ‏ ‏هَمَزَاتِ ‏ ‏الشَّيَاطِينِ وَأَنْ ‏ ‏يَحْضُرُونِ ‏ ‏فَإِنَّهُ لَا يُضَرُّ ‏ ‏وَبِالْحَرِيِّ ‏ ‏أَنْ لَا يَقْرَبَكَ ‏","","",""],[15979,15979,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَامُ فِي حُجْرَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَسْمَعُهُ إِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏يُصَلِّي يَقُولُ ‏ ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏ ‏الْهَوِيَّ ‏ ‏قَالَ ثُمَّ يَقُولُ سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ ‏ ‏الْهَوِيَّ ‏","","",""],[15980,15980,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ كَعْبٍ الْأَسْلَمِيُّ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيتُ عِنْدَ بَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيهِ وَضُوءَهُ فَأَسْمَعُهُ بَعْدَ ‏ ‏هَوِيٍّ ‏ ‏مِنْ اللَّيْلِ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ وَأَسْمَعُهُ بَعْدَ ‏ ‏هَوِيٍّ ‏ ‏مِنْ اللَّيْلِ يَقُولُ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[15981,15981,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ أَبِيتُ عِنْدَ بَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيهِ وَضُوءَهُ فَأَسْمَعُهُ بَعْدَ ‏ ‏هَوِيٍّ ‏ ‏مِنْ اللَّيْلِ يَقُولُ ‏ ‏سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ‏ ‏وَالْهَوِيِّ ‏ ‏مِنْ اللَّيْلِ يَقُولُ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏","","",""],[15982,15982,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ الْأَسْلَمِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ أَخْدُمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏رَبِيعَةُ ‏ ‏أَلَا تَزَوَّجُ قَالَ قُلْتُ وَاللَّهِ يَا رَسُولَ اللَّهِ مَا أُرِيدُ أَنْ أَتَزَوَّجَ مَا عِنْدِي مَا ‏ ‏يُقِيمُ ‏ ‏الْمَرْأَةَ وَمَا أُحِبُّ أَنْ يَشْغَلَنِي عَنْكَ شَيْءٌ فَأَعْرَضَ عَنِّي فَخَدَمْتُهُ مَا خَدَمْتُهُ ثُمَّ قَالَ لِي الثَّانِيَةَ يَا ‏ ‏رَبِيعَةُ ‏ ‏أَلَا تَزَوَّجُ فَقُلْتُ مَا أُرِيدُ أَنْ أَتَزَوَّجَ مَا عِنْدِي مَا ‏ ‏يُقِيمُ ‏ ‏الْمَرْأَةَ وَمَا أُحِبُّ أَنْ يَشْغَلَنِي عَنْكَ شَيْءٌ فَأَعْرَضَ عَنِّي ثُمَّ رَجَعْتُ إِلَى نَفْسِي فَقُلْتُ وَاللَّهِ لَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا يُصْلِحُنِي فِي الدُّنْيَا وَالْآخِرَةِ أَعْلَمُ مِنِّي وَاللَّهِ لَئِنْ قَالَ تَزَوَّجْ لَأَقُولَنَّ نَعَمْ يَا رَسُولَ اللَّهِ مُرْنِي بِمَا شِئْتَ قَالَ فَقَالَ يَا ‏ ‏رَبِيعَةُ ‏ ‏أَلَا تَزَوَّجُ فَقُلْتُ بَلَى مُرْنِي بِمَا شِئْتَ قَالَ انْطَلِقْ إِلَى آلِ فُلَانٍ حَيٍّ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكَانَ فِيهِمْ ‏ ‏تَرَاخٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْ لَهُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْسَلَنِي إِلَيْكُمْ يَأْمُرُكُمْ أَنْ تُزَوِّجُونِي فُلَانَةَ لِامْرَأَةٍ مِنْهُمْ فَذَهَبْتُ فَقُلْتُ لَهُمْ إِنَّ رَسُولَ اللَّهِ أَرْسَلَنِي إِلَيْكُمْ ‏ ‏يَأْمُرُكُمْ أَنْ تُزَوِّجُونِي فُلَانَةَ فَقَالُوا مَرْحَبًا بِرَسُولِ اللَّهِ وَبِرَسُولِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَا يَرْجِعُ رَسُولُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا بِحَاجَتِهِ فَزَوَّجُونِي ‏ ‏وَأَلْطَفُونِي ‏ ‏وَمَا سَأَلُونِي ‏ ‏الْبَيِّنَةَ ‏ ‏فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَزِينًا فَقَالَ لِي مَا لَكَ يَا ‏ ‏رَبِيعَةُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَتَيْتُ قَوْمًا كِرَامًا فَزَوَّجُونِي وَأَكْرَمُونِي ‏ ‏وَأَلْطَفُونِي ‏ ‏وَمَا سَأَلُونِي ‏ ‏بَيِّنَةً ‏ ‏وَلَيْسَ عِنْدِي ‏ ‏صَدَاقٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏بُرَيْدَةُ الْأَسْلَمِيُّ ‏ ‏اجْمَعُوا لَهُ وَزْنَ ‏ ‏نَوَاةٍ ‏ ‏مِنْ ذَهَبٍ قَالَ فَجَمَعُوا لِي وَزْنَ ‏ ‏نَوَاةٍ ‏ ‏مِنْ ذَهَبٍ فَأَخَذْتُ مَا جَمَعُوا لِي فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اذْهَبْ بِهَذَا إِلَيْهِمْ فَقُلْ هَذَا ‏ ‏صَدَاقُهَا ‏ ‏فَأَتَيْتُهُمْ فَقُلْتُ هَذَا ‏ ‏صَدَاقُهَا ‏ ‏فَرَضُوهُ وَقَبِلُوهُ وَقَالُوا كَثِيرٌ طَيِّبٌ قَالَ ثُمَّ رَجَعْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَزِينًا فَقَالَ يَا ‏ ‏رَبِيعَةُ ‏ ‏مَا لَكَ حَزِينٌ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا رَأَيْتُ قَوْمًا أَكْرَمَ مِنْهُمْ رَضُوا بِمَا آتَيْتُهُمْ وَأَحْسَنُوا وَقَالُوا كَثِيرًا طَيِّبًا وَلَيْسَ عِنْدِي مَا ‏ ‏أُولِمُ ‏ ‏قَالَ يَا ‏ ‏بُرَيْدَةُ ‏ ‏اجْمَعُوا لَهُ شَاةً قَالَ فَجَمَعُوا لِي ‏ ‏كَبْشًا ‏ ‏عَظِيمًا سَمِينًا فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اذْهَبْ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْ لَهَا فَلْتَبْعَثْ ‏ ‏بِالْمِكْتَلِ ‏ ‏الَّذِي فِيهِ الطَّعَامُ قَالَ فَأَتَيْتُهَا فَقُلْتُ لَهَا مَا أَمَرَنِي بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ هَذَا ‏ ‏الْمِكْتَلُ ‏ ‏فِيهِ تِسْعُ ‏ ‏آصُعِ ‏ ‏شَعِيرٍ لَا وَاللَّهِ إِنْ أَصْبَحَ لَنَا طَعَامٌ غَيْرُهُ خُذْهُ فَأَخَذْتُهُ فَأَتَيْتُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَخْبَرْتُهُ مَا قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقَالَ اذْهَبْ بِهَذَا إِلَيْهِمْ فَقُلْ لِيُصْبِحْ هَذَا عِنْدَكُمْ خُبْزًا فَذَهَبْتُ إِلَيْهِمْ وَذَهَبْتُ ‏ ‏بِالْكَبْشِ ‏ ‏وَمَعِي أُنَاسٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَقَالَ لِيُصْبِحْ هَذَا عِنْدَكُمْ خُبْزًا وَهَذَا طَبِيخًا فَقَالُوا أَمَّا الْخُبْزُ ‏ ‏فَسَنَكْفِيكُمُوهُ وَأَمَّا ‏ ‏الْكَبْشُ ‏ ‏فَاكْفُونَا أَنْتُمْ فَأَخَذْنَا ‏ ‏الْكَبْشَ ‏ ‏أَنَا وَأُنَاسٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَذَبَحْنَاهُ وَسَلَخْنَاهُ وَطَبَخْنَاهُ فَأَصْبَحَ عِنْدَنَا خُبْزٌ وَلَحْمٌ ‏ ‏فَأَوْلَمْتُ ‏ ‏وَدَعَوْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَانِي أَرْضًا وَأَعْطَانِي ‏ ‏أَبُو بَكْرٍ ‏ ‏أَرْضًا وَجَاءَتْ الدُّنْيَا فَاخْتَلَفْنَا فِي ‏ ‏عِذْقِ ‏ ‏نَخْلَةٍ فَقُلْتُ أَنَا هِيَ فِي ‏ ‏حَدِّي ‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏هِيَ فِي ‏ ‏حَدِّي ‏ ‏فَكَانَ بَيْنِي وَبَيْنَ ‏ ‏أَبِي بَكْرٍ ‏ ‏كَلَامٌ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏كَلِمَةً كَرِهَهَا وَنَدِمَ فَقَالَ لِي يَا ‏ ‏رَبِيعَةُ ‏ ‏رُدَّ عَلَيَّ مِثْلَهَا حَتَّى تَكُونَ قِصَاصًا قَالَ قُلْتُ لَا أَفْعَلُ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏لَتَقُولَنَّ أَوْ ‏ ‏لَأَسْتَعْدِيَنَّ ‏ ‏عَلَيْكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ مَا أَنَا بِفَاعِلٍ قَالَ وَرَفَضَ الْأَرْضَ وَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْطَلَقْتُ ‏ ‏أَتْلُوهُ ‏ ‏فَجَاءَ نَاسٌ مِنْ ‏ ‏أَسْلَمَ ‏ ‏فَقَالُوا لِي رَحِمَ اللَّهُ ‏ ‏أَبَا بَكْرٍ ‏ ‏فِي أَيِّ شَيْءٍ ‏ ‏يَسْتَعْدِي ‏ ‏عَلَيْكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَالَ لَكَ مَا قَالَ فَقُلْتُ أَتَدْرُونَ مَا هَذَا هَذَا ‏ ‏أَبُو بَكْرٍ الصِّدِّيقُ ‏ ‏هَذَا ثَانِيَ اثْنَيْنِ وَهَذَا ‏ ‏ذُو شَيْبَةِ ‏ ‏الْمُسْلِمِينَ إِيَّاكُمْ لَا يَلْتَفِتُ ‏ ‏فَيَرَاكُمْ تَنْصُرُونِي عَلَيْهِ فَيَغْضَبَ فَيَأْتِيَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَغْضَبَ لِغَضَبِهِ فَيَغْضَبَ اللَّهُ عَزَّ وَجَلَّ لِغَضَبِهِمَا فَيُهْلِكَ ‏ ‏رَبِيعَةَ ‏ ‏قَالُوا مَا تَأْمُرُنَا قَالَ ارْجِعُوا قَالَ فَانْطَلَقَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَبِعْتُهُ وَحْدِي حَتَّى أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثَهُ الْحَدِيثَ كَمَا كَانَ فَرَفَعَ إِلَيَّ رَأْسَهُ فَقَالَ يَا ‏ ‏رَبِيعَةُ ‏ ‏مَا لَكَ ‏ ‏وَلِلصِّدِّيقِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَانَ كَذَا كَانَ كَذَا قَالَ لِي كَلِمَةً كَرِهَهَا فَقَالَ لِي قُلْ كَمَا قُلْتُ حَتَّى يَكُونَ قِصَاصًا فَأَبَيْتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجَلْ فَلَا تَرُدَّ عَلَيْهِ وَلَكِنْ قُلْ غَفَرَ اللَّهُ لَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَقُلْتُ غَفَرَ اللَّهُ لَكَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏فَوَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَبْكِي ‏","","",""],[15983,15983,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلْنِي أُعْطِكَ قُلْتُ يَا رَسُولَ اللَّهِ أَنْظِرْنِي أَنْظُرْ فِي أَمْرِي قَالَ فَانْظُرْ فِي أَمْرِكَ قَالَ فَنَظَرْتُ فَقُلْتُ إِنَّ أَمْرَ الدُّنْيَا يَنْقَطِعُ فَلَا أَرَى شَيْئًا خَيْرًا مِنْ شَيْءٍ آخُذُهُ لِنَفْسِي لِآخِرَتِي فَدَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا حَاجَتُكَ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏اشْفَعْ لِي إِلَى رَبِّكَ عَزَّ وَجَلَّ فَلْيُعْتِقْنِي مِنْ النَّارِ فَقَالَ مَنْ أَمَرَكَ بِهَذَا فَقُلْتُ لَا وَاللَّهِ يَا رَسُولَ اللَّهِ مَا أَمَرَنِي بِهِ أَحَدٌ وَلَكِنِّي نَظَرْتُ فِي أَمْرِي فَرَأَيْتُ أَنَّ الدُّنْيَا زَائِلَةٌ مِنْ أَهْلِهَا فَأَحْبَبْتُ أَنْ آخُذَ لِآخِرَتِي قَالَ فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ ‏","","",""],[15984,15984,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏نُعَيْمٍ الْمُجْمِرِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَخْدُمُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَقُومُ لَهُ فِي حَوَائِجِهِ نَهَارِي أَجْمَعَ حَتَّى يُصَلِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ الْآخِرَةَ فَأَجْلِسَ بِبَابِهِ إِذَا دَخَلَ بَيْتَهُ أَقُولُ لَعَلَّهَا أَنْ تَحْدُثَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَةٌ فَمَا أَزَالُ أَسْمَعُهُ يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ سُبْحَانَ اللَّهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ حَتَّى أَمَلَّ فَأَرْجِعَ أَوْ تَغْلِبَنِي عَيْنِي فَأَرْقُدَ قَالَ فَقَالَ لِي يَوْمًا لِمَا يَرَى مِنْ ‏ ‏خِفَّتِي ‏ ‏لَهُ وَخِدْمَتِي إِيَّاهُ سَلْنِي يَا ‏ ‏رَبِيعَةُ ‏ ‏أُعْطِكَ قَالَ فَقُلْتُ أَنْظُرُ فِي أَمْرِي يَا رَسُولَ اللَّهِ ثُمَّ أُعْلِمُكَ ذَلِكَ قَالَ فَفَكَّرْتُ فِي نَفْسِي فَعَرَفْتُ أَنَّ الدُّنْيَا مُنْقَطِعَةٌ زَائِلَةٌ وَأَنَّ لِي فِيهَا رِزْقًا ‏ ‏سَيَكْفِينِي ‏ ‏وَيَأْتِينِي قَالَ فَقُلْتُ أَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِآخِرَتِي فَإِنَّهُ مِنْ اللَّهِ عَزَّ وَجَلَّ بِالْمَنْزِلِ الَّذِي هُوَ بِهِ قَالَ فَجِئْتُ فَقَالَ مَا فَعَلْتَ يَا ‏ ‏رَبِيعَةُ ‏ ‏قَالَ فَقُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ أَسْأَلُكَ أَنْ تَشْفَعَ لِي إِلَى رَبِّكَ فَيُعْتِقَنِي مِنْ النَّارِ قَالَ فَقَالَ مَنْ أَمَرَكَ بِهَذَا يَا ‏ ‏رَبِيعَةُ ‏ ‏قَالَ فَقُلْتُ لَا وَاللَّهِ الَّذِي بَعَثَكِ بِالْحَقِّ مَا أَمَرَنِي بِهِ أَحَدٌ وَلَكِنَّكَ لَمَّا قُلْتَ سَلْنِي أُعْطِكَ وَكُنْتَ مِنْ اللَّهِ بِالْمَنْزِلِ الَّذِي أَنْتَ بِهِ نَظَرْتُ فِي أَمْرِي وَعَرَفْتُ أَنَّ الدُّنْيَا مُنْقَطِعَةٌ وَزَائِلَةٌ وَأَنَّ لِي فِيهَا رِزْقًا ‏ ‏سَيَأْتِينِي فَقُلْتُ أَسْأَلُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِآخِرَتِي قَالَ فَصَمَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَوِيلًا ثُمَّ قَالَ لِي إِنِّي فَاعِلٌ فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ ‏","","",""],[15985,15985,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعُسْفَانَ ‏ ‏فَاسْتَقْبَلَنَا الْمُشْرِكُونَ عَلَيْهِمْ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏وَهُمْ بَيْنَنَا وَبَيْنَ الْقِبْلَةِ ‏ ‏فَصَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ فَقَالُوا قَدْ كَانُوا عَلَى حَالٍ لَوْ أَصَبْنَا ‏ ‏غِرَّتَهُمْ ‏ ‏ثُمَّ قَالُوا تَأْتِي عَلَيْهِمْ الْآنَ صَلَاةٌ هِيَ أَحَبُّ إِلَيْهِمْ مِنْ أَبْنَائِهِمْ وَأَنْفُسِهِمْ قَالَ فَنَزَلَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بِهَذِهِ الْآيَاتِ بَيْنَ الظُّهْرِ وَالْعَصْرِ ‏ { ‏وَإِذَا كُنْتَ فِيهِمْ فَأَقَمْتَ لَهُمْ الصَّلَاةَ ‏} ‏قَالَ فَحَضَرَتْ فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذُوا السِّلَاحَ قَالَ فَصَفَفْنَا خَلْفَهُ صَفَّيْنِ قَالَ ثُمَّ رَكَعَ فَرَكَعْنَا جَمِيعًا ثُمَّ رَفَعَ فَرَفَعْنَا جَمِيعًا ثُمَّ سَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّفِّ الَّذِي ‏ ‏يَلِيهِ وَالْآخَرُونَ قِيَامٌ يَحْرُسُونَهُمْ فَلَمَّا سَجَدُوا وَقَامُوا جَلَسَ الْآخَرُونَ فَسَجَدُوا فِي مَكَانِهِمْ ثُمَّ تَقَدَّمَ هَؤُلَاءِ إِلَى مَصَافِّ هَؤُلَاءِ وَجَاءَ هَؤُلَاءِ إِلَى مَصَافِّ هَؤُلَاءِ قَالَ ثُمَّ رَكَعَ فَرَكَعُوا جَمِيعًا ثُمَّ رَفَعَ فَرَفَعُوا جَمِيعًا ثُمَّ سَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالصَّفُّ الَّذِي يَلِيهِ وَالْآخَرُونَ قِيَامٌ يَحْرُسُونَهُمْ فَلَمَّا جَلَسَ جَلَسَ الْآخَرُونَ فَسَجَدُوا فَسَلَّمَ عَلَيْهِمْ ثُمَّ انْصَرَفَ قَالَ فَصَلَّاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتَيْنِ مَرَّةً ‏ ‏بِعُسْفَانَ ‏ ‏وَمَرَّةً بِأَرْضِ ‏ ‏بَنِي سُلَيْمٍ ‏","","",""],[15986,15986,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُجَاهِدًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَتَبَ بِهِ إِلَيَّ وَقَرَأْتُهُ عَلَيْهِ وَسَمِعْتُهُ مِنْهُ يُحَدِّثُ بِهِ وَلَكِنِّي حَفِظْتُهُ مِنْ الْكِتَابِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي مَصَافِّ الْعَدُوِّ ‏ ‏بِعُسْفَانَ ‏ ‏وَعَلَى الْمُشْرِكِينَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَصَلَّى بِهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ثُمَّ قَالَ الْمُشْرِكُونَ إِنَّ لَهُمْ صَلَاةً بَعْدَ هَذِهِ هِيَ أَحَبُّ إِلَيْهِمْ مِنْ أَبْنَائِهِمْ وَأَمْوَالِهِمْ ‏ ‏فَصَلَّى بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَصْرَ فَصَفَّهُمْ صَفَّيْنِ خَلْفَهُ قَالَ فَرَكَعَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمِيعًا فَلَمَّا رَفَعُوا رُءُوسَهُمْ سَجَدَ الصَّفُّ الَّذِي يَلِيهِ وَقَامَ الْآخَرُونَ فَلَمَّا رَفَعُوا رُءُوسَهُمْ سَجَدَ الصَّفُّ الْمُؤَخَّرُ لِرُكُوعِهِمْ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ تَأَخَّرَ الصَّفُّ الْمُقَدَّمُ وَتَقَدَّمَ الصَّفُّ الْمُؤَخَّرُ فَقَامَ كُلُّ وَاحِدٍ مِنْهُمْ فِي مَقَامِ صَاحِبِهِ ثُمَّ رَكَعَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمِيعًا فَلَمَّا رَفَعُوا رُءُوسَهُمْ مِنْ الرُّكُوعِ سَجَدَ الصَّفُّ الَّذِي يَلِيهِ وَقَامَ الْآخَرُونَ ثُمَّ سَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمْ ‏","","",""],[15987,15987,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ الزُّرَقِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ وَالْمُشْرِكُونَ بَيْنَهُمْ وَبَيْنَ الْقِبْلَةِ مَرَّتَيْنِ مَرَّةً بِأَرْضِ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏وَمَرَّةً ‏ ‏بِعُسْفَانَ ‏","","",""],[15988,15988,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي عَيَّاشٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ حِينَ أَصْبَحَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ كَانَ لَهُ ‏ ‏كَعَدْلِ ‏ ‏رَقَبَةٍ مِنْ وَلَدِ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَكُتِبَ لَهُ بِهَا عَشْرُ حَسَنَاتٍ وَحُطَّ عَنْهُ بِهَا عَشْرُ سَيِّئَاتٍ وَرُفِعَتْ لَهُ بِهَا عَشْرُ دَرَجَاتٍ وَكَانَ فِي ‏ ‏حِرْزٍ ‏ ‏مِنْ الشَّيْطَانِ حَتَّى يُمْسِيَ وَإِذَا أَمْسَى مِثْلُ ذَلِكَ حَتَّى يُصْبِحَ قَالَ فَرَأَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَرَى النَّائِمُ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا عَيَّاشٍ ‏ ‏يَرْوِي عَنْكَ كَذَا وَكَذَا قَالَ صَدَقَ ‏ ‏أَبُو عَيَّاشٍ ‏","","",""],[15989,15989,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْقَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَمْرِو بْنِ الْقَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدِمَ فَخَلَّفَ ‏ ‏سَعْدًا ‏ ‏مَرِيضًا حَيْثُ خَرَجَ إِلَى ‏ ‏حُنَيْنٍ ‏ ‏فَلَمَّا قَدِمَ مِنْ ‏ ‏جِعِرَّانَةَ ‏ ‏مُعْتَمِرًا دَخَلَ عَلَيْهِ وَهُوَ وَجِعٌ مَغْلُوبٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي مَالًا وَإِنِّي أُورَثُ ‏ ‏كَلَالَةً ‏ ‏أَفَأُوصِي بِمَالِي كُلِّهِ أَوْ أَتَصَدَّقُ بِهِ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِثُلُثَيْهِ قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي ‏ ‏بِشَطْرِهِ ‏ ‏قَالَ لَا قَالَ ‏ ‏أَفَأُوصِي بِثُلُثِهِ قَالَ نَعَمْ وَذَاكَ كَثِيرٌ قَالَ أَيْ رَسُولَ اللَّهِ أَمُوتُ بِالدَّارِ الَّتِي خَرَجْتُ مِنْهَا مُهَاجِرًا قَالَ إِنِّي لَأَرْجُو أَنْ يَرْفَعَكَ اللَّهُ ‏ ‏فَيَنْكَأَ ‏ ‏بِكَ أَقْوَامًا وَيَنْفَعَ بِكَ آخَرِينَ يَا ‏ ‏عَمْرُو بْنَ الْقَارِيِّ ‏ ‏إِنْ مَاتَ ‏ ‏سَعْدٌ ‏ ‏بَعْدِي فَهَا هُنَا فَادْفِنْهُ نَحْوَ طَرِيقِ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَشَارَ بِيَدِهِ هَكَذَا ‏","","",""],[15990,15990,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرٍو الْقُرَشِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ شَهِدَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَ بِرَجْمِ رَجُلٍ بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏فَلَمَّا أَصَابَتْهُ ‏ ‏الْحِجَارَةُ فَرَّ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَهَلَّا تَرَكْتُمُوهُ ‏","","",""],[15991,15991,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّازَّقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ الصَّنْعَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏فَنَّجُ ‏ ‏قَالَ ‏ ‏كُنْتُ أَعْمَلُ فِي ‏ ‏الدَّيْنَبَاذِ ‏ ‏وَأُعَالِجُ فِيهِ فَقَدِمَ ‏ ‏يَعْلَي بْنُ أُمَيَّةَ ‏ ‏أَمِيرًا عَلَى ‏ ‏الْيَمَنِ ‏ ‏وَجَاءَ مَعَهُ رِجَالٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَنِي رَجُلٌ مِمَّنْ قَدِمَ مَعَهُ وَأَنَا فِي الزَّرْعِ أَصْرِفُ الْمَاءَ فِي الزَّرْعِ وَمَعَهُ فِي كُمِّهِ جَوْزٌ فَجَلَسَ عَلَى سَاقِيَةٍ مِنْ الْمَاءِ وَهُوَ يَكْسِرُ مِنْ ذَلِكَ الْجَوْزِ وَيَأْكُلُ ثُمَّ أَشَارَ إِلَى ‏ ‏فَنَّجَ ‏ ‏فَقَالَ يَا فَارِسِيُّ هَلُمَّ قَالَ فَدَنَوْتُ مِنْهُ فَقَالَ الرَّجُلُ ‏ ‏لِفَنَّجَ ‏ ‏أَتَضْمَنُ لِي غَرْسَ هَذَا الْجَوْزِ عَلَى الْمَاءِ فَقَالَ لَهُ ‏ ‏فَنَّجُ ‏ ‏مَا يَنْفَعُنِي ذَلِكَ فَقَالَ ‏ ‏الرَّجُلُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ بِأُذُنَيَّ هَاتَيْنِ ‏ ‏مَنْ نَصَبَ شَجَرَةً فَصَبَرَ عَلَى حِفْظِهَا وَالْقِيَامِ عَلَيْهَا حَتَّى تُثْمِرَ كَانَ لَهُ فِي كُلِّ شَيْءٍ يُصَابُ مِنْ ثَمَرَتِهَا ‏ ‏صَدَقَةٌ ‏ ‏عِنْدَ اللَّهِ عَزَّ وَجَلَّ فَقَالَ ‏ ‏فَنَّجُ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏فَنَّجُ ‏ ‏فَأَنَا أَضْمَنُهَا قَالَ فَمِنْهَا جَوْزُ ‏ ‏الدَّيْنَبَاذِ ‏","","",""],[15992,15992,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ طَارِقِ بْنِ عَلْقَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَمِّهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا جَاءَ مَكَانًا مِنْ دَارِ ‏ ‏يَعْلَى ‏ ‏نَسَبَهُ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏اسْتَقْبَلَ الْقِبْلَةَ فَدَعَا ‏ ‏و قَالَ ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏و قَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏عَنْ ‏ ‏أُمْهِ ‏","","",""],[15993,15993,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسَ ‏ ‏بِمِنًى ‏ ‏وَنَزَّلَهُمْ مَنَازِلَهُمْ وَقَالَ لِيَنْزِلْ ‏ ‏الْمُهَاجِرُونَ ‏ ‏هَاهُنَا وَأَشَارَ إِلَى مَيْمَنَةِ الْقِبْلَةِ ‏ ‏وَالْأَنْصَارُ ‏ ‏هَاهُنَا وَأَشَارَ إِلَى مَيْسَرَةِ الْقِبْلَةِ ثُمَّ لِيَنْزِلْ النَّاسُ حَوْلَهُمْ قَالَ وَعَلَّمَهُمْ ‏ ‏مَنَاسِكَهُمْ ‏ ‏فَفُتِّحَتْ أَسْمَاعُ أَهْلِ ‏ ‏مِنًى ‏ ‏حَتَّى سَمِعُوهُ فِي مَنَازِلِهِمْ قَالَ فَسَمِعْتُهُ يَقُولُ ‏ ‏ارْمُوا ‏ ‏الْجَمْرَةَ ‏ ‏بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَمِعْتُ ‏ ‏مُصْعَبًا الزُّبَيْرِيَّ ‏ ‏يَقُولُ جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏الْقَاصُّ ‏ ‏إِلَى ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَبْدِ اللَّهِ ‏ ‏إِنَّ قَوْمًا قَدْ نَهَوْنِي أَنْ ‏ ‏أَقُصَّ ‏ ‏هَذَا الْحَدِيثَ صَلَّى اللَّهُ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏إِنَّكَ حَمِيدٌ مَجِيدٌ وَعَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى أَهْلِ بَيْتِهِ وَعَلَى أَزْوَاجِهِ فَقَالَ ‏ ‏مَالِكٌ ‏ ‏حَدِّثْ بِهِ ‏ ‏وَقُصَّ ‏ ‏بِهِ ‏ ‏وَقُولَهُ ‏","","",""],[15994,15994,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاذٍ التَّيْمِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15995,15995,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَيَكُونُ قَوْمٌ لَهُمْ عَهْدٌ فَمَنْ قَتَلَ رَجُلًا مِنْهُمْ لَمْ ‏ ‏يَرَحْ ‏ ‏رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا ‏","","",""],[15996,15996,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ صَيْفِيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏صُهَيْبًا ‏ ‏قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَيْنَ يَدَيْهِ تَمْرٌ وَخُبْزٌ فَقَالَ ‏ ‏ادْنُ فَكُلْ قَالَ فَأَخَذَ يَأْكُلُ مِنْ التَّمْرِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ بِعَيْنِكَ ‏ ‏رَمَدًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّمَا آكُلُ مِنْ النَّاحِيَةِ ‏ ‏الْأُخْرَى قَالَ فَتَبَسَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15997,15997,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْحَضْرَمِيِّ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏مَنْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أُمَّتِي قَوْمًا يُعْطَوْنَ مِثْلَ أُجُورِ أَوَّلِهِمْ فَيُنْكِرُونَ الْمُنْكَرَ ‏","","",""],[15998,15998,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏حَارِثَةَ بْنِ مُضَرِّبٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِأَصْحَابِهِ ‏ ‏إِنَّ مِنْكُمْ رِجَالًا لَا أُعْطِيهِمْ شَيْئًا أَكِلُهُمْ مِنْهُمْ ‏ ‏فُرَاتُ بْنُ حَيَّانَ ‏ ‏قَالَ مِنْ ‏ ‏بَنِي عِجْلٍ ‏","","",""],[15999,15999,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو زُمَيْلٍ سِمَاكٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَنِي هِلَالٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَصْلُحُ ‏ ‏الصَّدَقَةُ ‏ ‏لِغَنِيٍّ وَلَا لِذِي ‏ ‏مِرَّةٍ ‏ ‏سَوِيٍّ ‏","","",""],[16000,16000,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَكْرُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏رَجُلٌ ‏ ‏خَدَمَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَمَانِ سِنِينَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قُرِّبَ إِلَيْهِ طَعَامُهُ يَقُولُ ‏ ‏بِسْمِ اللَّهِ وَإِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ اللَّهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ وَأَغْنَيْتَ ‏ ‏وَأَقْنَيْتَ ‏ ‏وَهَدَيْتَ وَأَحْيَيْتَ فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ ‏","","",""]];
